			{id=3451,title="Gravity Strike",body="The Twilight Drakonid strikes its current enemy target with a magically imbued attack. The strike inflicts $76561s1% of the target's current health as Physical damage, and reduces the target's Attack Power by $76561s2 for $76561d."},
			{id=3452,title="Grievous Whirl",body="The Twilight Drakonid swings its weapons around him, attacking all enemies within $76524A1 yards. The attack deals $76524s1 Physical damage, causes the targets to bleed for an additional $76524s2 Physical damage every $76524t2 seconds for $76524d. The bleed effect is also removed if the inflicted target becomes fully healed again."},
			{id=3453,title="Shadow Strike",body="The Twilight Drakonid steps through the shadows and reappears behind his current enemy target. After the Twilight Drakonid reappears, he inflicts $82362s2 Shadow damage to his target."},
		},
	},
	[107]={
		encounterID=107,
		instanceID=66,
		order=3,
		name="Karsh Steelbender",
		lore="The enormous drakonid Karsh Steelbender toils in the Twilight Forge, shaping weapons of war out of rare quicksilver. Although Karsh's works are nearly unbreakable under normal circumstances, at high temperatures they become as brittle as rusted iron.",
		dungeonEncounterID=1039,
		uiMapID=284,
		pin={x=0.4701,y=0.6647},
		difficultyIDs={1,2,24},
		npcIDs={39698},
