			{id=2379,title="Flamebreak",body="Beauty inflicts $76032s1 Fire damage to all nearby enemies within $76032A1 yards and knocks them back."},
			{id=2380,title="Terrifying Roar",body="Beauty roars, causing all nearby enemies to flee in fear for $76028d."},
			{id=2381,title="Magma Spit",body="Beauty spits magma at a random enemy player, inflicting $76031s1 Fire damage and an additional $76031s2 Fire damage every $76031t2 seconds for $76031d. When the magma spit expires or is removed, four additional magma blobs are launched from the player to locations $76058a2 yards away. When these magma blobs land, nearby players within $76070a1 yards are dealt $76070s1 Fire damage."},
			{id=2382,title="Lucky, Spot, and Buster",body="In Heroic Difficulty, two of the three pups of Beauty will fight with Beauty. Engaging either of the two pups will cause Beauty to also attack the players.",difficultyIDs={2,4,5,6}},
			{id=2383,title="Lava Drool",body="The pup's lava drool collects into a pool, and any player standing within this lava pool is dealt $76628s2 Fire damage every $76628t2 seconds. The pools last $76628d before dissipating.",difficultyIDs={2,4,5,6}},
			{id=2384,title="Little Big Flame Breath",body="Beauty's pups channel a flame breath at their current enemy target for $76665d. The target is dealt $76665s1 Fire damage every second.",difficultyIDs={2,4,5,6}},
		},
	},
	[109]={
