		sections={
			{id=2385,title="Transformation",body="When Ascendant Lord Obsidius reaches 69% and 34% of his remaining health, he will randomly target one of the Shadows of Obsidius and jump into it. This results in Obsidius and the Shadow switching places."},
			{id=2386,title="Stone Blow",body="Ascendant Lord Obsidius strikes with a strong attack, inflicting $76185s1% of his normal melee damage and stunning his current enemy target for $76185d."},
			{id=2387,title="Twilight Corruption",body="Ascendant Lord Obsidius corrupts a random enemy player, inflicting $76188s1 Shadow damage every $76188t1 seconds for $76188d."},
			{id=2388,title="Thunderclap",body="Ascendant Lord Obsidius slams the ground, inflicting $76186s1 Nature damage and reducing the movement speed of nearby enemies within $76186A1 yards by $76186s2% for $76186d.",difficultyIDs={2,4,5,6}},
			{id=2389,title="Shadow of Obsidius",body="Ascendant Lord Obsidius fights alongside two Shadows of Obsidius. These ephemeral constructs absorb all incoming damage.$[!2,4\n\nIn Heroic Difficulty, Ascendant Lord Obsidius will fight with three Shadows of Obsidius.$]"},
			{id=2390,title="Twitchy",body="Shadows of Obsidius will attack the enemy who has most recently generated threat, instead of the enemy with the greatest amount of threat.",difficultyIDs={2,4,5,6}},
			{id=2391,title="Crepuscular Veil",body="Shadows of Obsidius that swing at their current enemy cause all healing dealt to their target to be reduced by $76189s1% for $76189d. This effect stacks up to 4 times.",difficultyIDs={2,4,5,6}},
		},
