			{id=2412,title="Curse of Blood",body="High Priestess Azil curses a random enemy player, increasing the player's Physical damage taken by $79345s1 for $79345d."},
			{id=2413,title="Force Grip",body="High Priestess Azil traps her current enemy target in a field of energy for $79351d, repeatedly lifting them up and then slamming them into the ground. Each time the target is slammed into the ground, they are dealt $79358s2 Physical damage."},
			{id=2414,title="Gravity Well",body="High Priestess Azil summons a Gravity Well at the location of a random player. After 3 seconds, the Gravity Well fully forms and will then pull any nearby target within $79332A1 yards of the well's center towards it. A Gravity Well will also inflict Shadow damage every $79244t1 second to any target within the well. The damage inflicted is increased the closer the target is to the center of the Gravity Well. Gravity Wells have a duration of 20 seconds.$[!2,4\n\nIn Heroic Difficulty a Gravity Well no longer has a set duration. If a Gravity Well kills a unit, they shrink in size by 25%. So after killing 4 units, they disappear.$]"},
			{id=2415,title="Devout Follower",body="Devout Followers rush to help High Priestess Azil during the fight. These creatures have very low health."},
			{id=2416,title="Stage Two: Feel the Fury of Earth!",body="High Priestess Azil begins this stage by casting Energy Shield, then she hovers up to her altar where she will cast Seismic Shard three times. After finishing casting the Seismic Shard spells, she returns to the ground. Many more Devout Followers rush to help Azil during this stage."},
			{id=2417,title="Energy Shield",body="High Priestess Azil creates an Energy Shield around her which reduces the damage she takes by $79050s1%. When the shield is initially created, any enemy target within $79050A3 yards is dealt $79050s3 Arcane damage and knocked back."},
			{id=2418,title="Seismic Shard",body="High Priestess Azil magically raises up a huge shard of stone, then throws it at the location of a random enemy player. When the shard lands it inflicts $79021s1 damage to all units within $79021A1 yards."},
		},
	},
