	[117]={
		encounterID=117,
		instanceID=69,
		order=1,
		name="General Husam",
		lore="The titans themselves appointed General Husam as one of Uldum's foremost guardians. After Siamat, Lord of the South Wind, cured the Neferset tol'vir's curse of flesh, Husam helmed a rebellion that culminated in the air elemental's imprisonment.",
		dungeonEncounterID=1052,
		uiMapID=277,
		pin={x=0.3752,y=0.4251},
		difficultyIDs={1,2,24},
		npcIDs={44577},
