		sections={
			{id=2437,title="Shockwave",body="General Husam prepares to unleash a massive blow, then he strikes the ground and four separate Shockwaves erupt from his location. Each Shockwave travels along the ground in a different direction, inflicting $83454s1 Physical damage to any enemy within $83454A1 yards of a Shockwave."},
			{id=2438,title="Bad Intentions",body="General Husam charges a random enemy player then hurls them onto a nearby wall. The hard impact from being thrown onto the wall inflicts $83339s1 Physical damage on the player, and they are stunned as they slide down the wall back onto the ground."},
			{id=2439,title="Hammer Fist",body="General Husam executes a rapid flurry of four attacks, with one landing every $83654t1 second for $83654d. Each Hammer First attack inflicts $83655s1% of his normal melee damage."},
			{id=2440,title="Mystic Trap",body="General Husam periodically throws mystic traps at the location of three random players. After two seconds, the trap fully arms and any player located within $83112A1 yards of the trap will cause it to detonate. A Mystic Trap detonating inflicts $83171s1 Fire damage to all players within $83171A1 yards and knock them back.\n\nThe traps stay armed for 20 seconds then begin a 5 second countdown. After this final 5 second countdown ends, the Mystic Trap will detonate."},
			{id=2441,title="Detonate Traps",body="General Husam prematurely begins the final 5 second countdown sequence for all active mystic traps. After the countdown ends, every trap will detonate.",difficultyIDs={2,4,5,6}},
		},
	},
	[118]={
		encounterID=118,
		instanceID=69,
		order=2,
		name="Lockmaw",
		lore="Amid the Neferset's chaotic insurrection against Siamat, the pygmy Augh pilfered whatever treasures he could from the ancient tol'vir city. Among his race, Augh is respected as much for his cunning as he is for his ferocious pet crocolisk, Lockmaw.",
		dungeonEncounterID=1054,
		uiMapID=277,
		pin={x=0.6747,y=0.7246},
		difficultyIDs={1,2,24},
		npcIDs={43614},
		displayIDs={33438,37339},
		loot={
			{itemID=133263,diffs={24},faction=-1},
			{itemID=133261,diffs={24},faction=-1},
			{itemID=133278,diffs={24},faction=-1},
