			{itemID=55870,diffs={},faction=-1},
		},
		sections={
			{id=2442,title="Lockmaw"},
			{id=2443,title="Viscous Poison",body="Lockmaw spits a glob of poison onto the location of a random player, inflicting $81630s1 Nature damage to every player within $81630A1 yards of the location, slowing their movement speed by $81630s2%, and additionally inflicting $81630s3 Nature damage every $81630t3 seconds for $81630d."},
			{id=2444,title="Dust Flail",body="Lockmaw begins to whip his tail up and down for $81643d. Lockmaw deals $81644s1 Nature damage every second to players behind him and their chance to hit is reduced by $81673s1% for $81673d. The damage dealt by Dust Flail increases by $81644s3% for each second Lockmaw whips his tail."},
			{id=2445,title="Venomous Rage",body="When Lockmaw's remaining health reaches 30%, he enters a Venomous Rage. This increases his damage dealt by $81706s1%."},
			{id=2446,title="Scent of Blood",body="Lockmaw causes a random player to bleed, inflicting $81690s1 Physical damage every $81690t1 seconds for $81690d. The scent of the blood causes Frenzied Crocolisks to attack the affected player."},
			{id=2447,title="Frenzied Crocolisk",body="These vicious crocolisks periodically join the fight from the nearby riverbeds. They try to attack any player who has the Scent of Blood effect on them."},
			{id=2448,title="Vicious Bite",body="Frenzied Crocolisks bite their current enemy target, inflicting Physical damage equal to $81677s1% of a normal melee attack and additionally inflicting $81677s2 Physical damage every $81677t2 seconds for $81677d. The Vicious Bite stacks up to 3 times."},
			{id=2449,title="Augh",body="While Lockmaw is alive, Augh is immune to damage and will periodically enter the fight stealthed then use his Paralytic Blow Dart, Whirlwind, or Smoke bomb abilities before retreating.$[!2,4\n\nAfter Lockmaw dies in Heroic Difficulty, Augh steals Lockmaw's loot and becomes attackable.$]"},
			{id=2450,title="Paralytic Blow Dart",body="Augh shoots a Paralytic Blow Dart at a random player, immediately inflicting $84799s1 Nature damage, reducing melee, ranged, and spell casting speeds by $84799s3%, and additionally inflicting $84799s2 Nature damage every $84799t2 seconds for $84799d."},
			{id=2451,title="Whirlwind",body="Augh spins around like mad towards a random player for $84784d, inflicting $84785s1 Physical damage every second to surrounding enemies within $84785A1 yards."},
			{id=2452,title="Smoke Bomb",body="Augh explodes a Smoke Bomb at his feet, stunning any enemy target within $84768A1 yards for $84768d."},
			{id=2453,title="Frenzy",body="Augh enters a Frenzy, increasing his attack speed by $91415s1% and damage dealt by $91415s3%.",difficultyIDs={2,4,5,6}},
			{id=2454,title="Dragon's Breath",body="Augh breathes fire in a $83776a1 yard long 60 degree frontal cone, inflicting $83776s1 Fire damage to every enemy target within the cone and disorienting them for $83776d.",difficultyIDs={2,4,5,6}},
		},
	},
	[119]={
		encounterID=119,
		instanceID=69,
		order=3,
		name="High Prophet Barim",
		lore="High Prophet Barim is the hallowed spiritual leader of the Neferset. Along with General Husam, he rallied his fellow Neferset against Siamat and imprisoned the air elemental. Regardless, some dark force still drives Barim and his followers to terrorize Uldum.",
		dungeonEncounterID=1053,
		uiMapID=277,
		pin={x=0.2705,y=0.6572},
		difficultyIDs={1,2,24},
		npcIDs={43612},
		displayIDs={34744},
		loot={
			{itemID=133264,diffs={24},faction=-1},
			{itemID=133276,diffs={24},faction=-1},
			{itemID=133277,diffs={24},faction=-1},
