		sections={
			{id=2474,title="Stage One: Winds of the South, Rise!",body="Siamat begins the encounter flying above his platform, nigh invulnerable to any damage taken."},
			{id=2475,title="Storm Bolt",body="Siamat throws a charged missile at a random enemy player, inflicting $73564s1 Nature damage."},
			{id=2476,title="Cloud Burst",body="Siamat targets a random player's location and summons a $83051A1 yard radius cloud ring there. After 3 seconds the cloud bursts, inflicting $83051s1 Nature damage and knocking up any player standing in the cloud every second for 3 sec."},
			{id=2477,title="Servant of Siamat",body="Siamat summons three of these large air elementals during Stage 1. A single Servant enters the fight every 45 seconds, or immediately after the previous Servant dies. After all three Servants die, Siamat enters Stage Two."},
			{id=2478,title="Lightning Nova",body="The Servant of Siamat emits a circular pulse of energy that inflicts $84544s1 Nature damage to all enemies within $84544A1 yards."},
			{id=2479,title="Thunder Crash",body="The Servant of Siamat builds up a massive charge of electricity then unleashes the energy at his current target inflicting $84522s1 Nature damage."},
			{id=2480,title="Lightning Charge",body="When a Servant of Siamat reaches 4% of its remaining health, it emits a Lightning Charge inflicting $91872s1 Nature damage, increasing damage taken by $93959s2%, damage dealt increased by $91871s1%, and increasing haste by $91871s3% for every player within $91872A1 yards.",difficultyIDs={2,4,5,6}},
			{id=2481,title="Minion of Siamat",body="Siamat summons these air elementals to join the fight approximately every 30 seconds in both Stages."},
			{id=2482,title="Chain Lightning",body="The Minion of Siamat strikes a random player with a lightning bolt that then arcs up to 10 yards to four additional players. The bolt inflicts $83455s1 Nature damage to the first target, then 70% less each time the bolt arcs to a new target."},
			{id=2483,title="Tempest Storm",body="When the Minion of Siamat reaches 5% of its remaining health, it unleashes a $83446A1 yard radius storm above him that slowly moves around the platform. Any player standing under the storm takes $83446s1 Nature damage every second."},
			{id=2484,title="Depletion",body="The Minion of Siamat slowly depletes its power over time and loses $84550s1% of its health every $84550t2 seconds."},
			{id=2485,title="Stage Two: Cower Before the Storm!",body="After the players kill three Servants of Siamat, Stage two begins with Siamat landing on the platform and becoming vulnerable to damage."},
			{id=2486,title="Wailing Winds",body="Siamat begins stage two by inflicting $83094s1 Nature damage to all players every second for $83066d. Players are also violently knocked around the platform during the spell."},
			{id=2487,title="Storm Bolt",body="In stage two, the Storm Bolt inflicts $91853s1 Nature damage."},
			{id=2488,title="Gathered Storms",body="Siamat absorbs a Tempest Storm formed by a Minion of Siamat. After absorbing the storm, Siamat blasts two players every second for $84987s1 Nature damage for $84982d.$[!2,4\n\nIn Heroic Difficulty Siamat blasts all players instead of two.$]"},
		},
	},
	[124]={
		encounterID=124,
		instanceID=70,
		order=1,
		name="Temple Guardian Anhuur",
		lore="In the final days of the Halls of Origination's use by titanic forces, Temple Guardian Anhuur was endowed with the willpower needed to wield the Light. Thus empowered, he was charged with judging the purity of those entering the facility.",
		dungeonEncounterID=1080,
		uiMapID=297,
		pin={x=0.5848,y=0.6272},
		difficultyIDs={1,2},
		npcIDs={39425},
		displayIDs={35067},
		loot={
			{itemID=56409,diffs={},faction=-1},
			{itemID=56410,diffs={},faction=-1},
			{itemID=56411,diffs={},faction=-1},
			{itemID=56407,diffs={},faction=-1},
			{itemID=56408,diffs={},faction=-1},
			{itemID=55886,diffs={},faction=-1},
			{itemID=55887,diffs={},faction=-1},
			{itemID=55888,diffs={},faction=-1},
			{itemID=55889,diffs={},faction=-1},
			{itemID=55890,diffs={},faction=-1},
		},
		sections={
			{id=2489,title="Burning Light",body="A beam of Holy energy erupts from an ornate decoration on the wall, creating a $75117A2 yard radius area of Burning Light on Anhuur's platform for $75114d. The Burning Light inflicts $75117s1 Holy damage every second to players standing within the area."},
			{id=2490,title="Divine Reckoning",body="Temple Guardian Anhuur places a Divine Reckoning on a random player. After $75592t2 seconds, the target and all other players within $75591A1 yards of the target take $75592s1 Holy damage and heal Temple Guardian Anhuur for five times the amount of damage dealt."},
			{id=2491,title="Shield of Light",body="When Temple Guardian Anhuur reaches 66% and 33% of his remaining health, he channels energy from two nearby beacons and erects a Shield of Light that makes him immune to damage and spell school interrupts. The energy powering the shield can be disrupted by activating the two Beacons of Light in the pit below Anhuur's platform.$[!2,4\n\nIn Heroic Difficulty, activating a Beacon of Light requires 10 seconds to complete.$]"},
			{id=2492,title="Reverberating Hymn",body="After Anhuur casts Shield of Light, he then immediately channels a Reverberating Hymn. The song inflicts $75323s1 Holy damage to all players every $75323t1 seconds.This effect stacks every 4 seconds as Anhuur continues to channel the song."},
			{id=2493,title="Pit Viper",body="These snakes inhabit the pit below Anhuur's platform."},
			{id=2494,title="Poison-tipped Fangs",body="Poison from the viper's fangs inflicts $74538s1 Nature damage every $74538t1 seconds for $74538d."},
		},
	},
	[125]={
		encounterID=125,
		instanceID=70,
		order=2,
		name="Earthrager Ptah",
		lore="Outside Earthrager Ptah's tomb, the sand is littered with the bones of creatures purified by Anhuur. It is said that Ptah can bend these remains to his will and send them against beings who manage to elude the facility's first line of defense.",
		dungeonEncounterID=1076,
		uiMapID=298,
		pin={x=0.5,y=0.4925},
		difficultyIDs={1,2},
		npcIDs={39428},
		displayIDs={31450},
		loot={
			{itemID=56424,diffs={},faction=-1},
			{itemID=56423,diffs={},faction=-1},
			{itemID=56425,diffs={},faction=-1},
			{itemID=56422,diffs={},faction=-1},
			{itemID=56426,diffs={},faction=-1},
			{itemID=56093,diffs={},faction=-1},
