		sections={
			{id=2602,title="Consuming Darkness",body="Argaloth envelops three players with Consuming Darkness, inflicting $88954s1 Shadow damage every $88954t1 sec. for $88954d.  The damage that Consuming Darkness inflicts greatly increases every $88954t1 sec.$[!4,6\n\nIn 25 player raids, Argaloth envelops eight players with Consuming Darkness.$]",difficultyIDs={3,4}},
			{id=2603,title="Meteor Slash",body="Argaloth slashes at his current target, inflicting $88942s1 Fire damage and increasing the Fire damage taken by $88942s2% for $88942d for all players within a frontal 120 degree cone . The damage divides amongst all targets slashed.",difficultyIDs={3,4}},
			{id=2604,title="Fel Firestorm",body="Argaloth unleashes a Fel Firestorm, rapidly creating $89000A1 yard radius Fel Flames around his cell for $88972d. Fel Flames inflict $89000s1 Fire damage every second to any player standing within them.",difficultyIDs={3,4}},
