		sections={
			{id=2605,title="Focused Fire",body="Occu'thar sets his gaze on the location of a random player, then for $96884d the gaze inflicts $97212s1 Fire damage every second and then $96883s1 Fire damage every second to players within $96883A1 yards of the targeted location.",difficultyIDs={3,4}},
			{id=2606,title="Searing Shadows",body="Occu'thar inflicts $96913s1 Shadow damage to players in a 60 degree cone in front of him, and increases Shadow damage taken by $96913s2% for $96913d.",difficultyIDs={3,4}},
			{id=2607,title="Eyes of Occu'thar",body="Occu'thar forms an Eye of Occu'thar on every player for $96942d. The eyes bore into their target hosts with the Gaze of Occu'thar.",difficultyIDs={3,4}},
			{id=2608,title="Gaze of Occu'thar",body="The Eye of Occu'thar gazes at its target host, inflicting $96946s1 Shadow damage every $96942t3 sec. for $96942d.",difficultyIDs={3,4}},
			{id=2609,title="Occu'thar's Destruction",body="After an Eye of Occu'thar remains attached to a player for $96942d, it fully bores into the host and detonates with Occu'thar's Destruction, inflicting $96968s1 Shadow damage on all players.",difficultyIDs={3,4}},
			{id=18670,title="Normal Difficulty Only",body="Baradin Hold is only available on Normal Difficulty.",difficultyIDs={5,6}},
