	[154]={
		encounterID=154,
		instanceID=74,
		order=1,
		name="The Conclave of Wind",
		lore="With Siamat, Lord of the South Wind, imprisoned by the Neferset tol'vir, Al'Akir's lieutenants are vying to fill the power vacuum that now exists in the Conclave of Wind. The remaining conclave members are Anshal, Lord of the West Wind, whose gales can heal allies or poison enemies; Rohash, Lord of the East Wind, whose tempests can grind the mightiest mountains to dust; and Nezir, Lord of the North Wind, whose frigid storms have claimed more lives than all other cardinal wind lords combined.",
		dungeonEncounterID=1035,
		uiMapID=328,
		pin={x=0.475,y=0.2605},
		difficultyIDs={1,2,3,4,5,6},
		npcIDs={45871},
