		sections={
			{id=3021,title="Stage One: Your Challenge is Accepted!",body="Al'Akir periodically casts Squall Line, Wind Burst, Ice Storm and Lightning Strike on random players. He casts Static Shock on any target in melee range and Electrocute on his primary target if that target leaves melee range."},
			{id=3022,title="Wind Burst",body="Al'Akir casts a Wind Burst on all players, inflicting $87770s1 Nature damage and knocking them back."},
			{id=3023,title="Squall Line",body="Al'Akir summons a line of wind funnels that move around the platform in a circle. The squalls catch any player that stands within $87855A1 yards, and inflict $87856s2 Nature damage per second for $87856d."},
			{id=3024,title="Ice Storm",body="Al'akir casts an Ice Storm at random locations around the platform. The Ice Storm slowly moves, leaving behind an ice patch on the ground. The ice inflicts $91020s1 Frost damage every $91020t1 seconds and reduces the movement speed by $91020s2% for all enemies standing within the ice patch."},
			{id=3025,title="Lightning Strike",body="Al'Akir casts a Lightning Strike at a random player, inflicting $88214s1 Nature damage to that player, and also $95764s1 Nature damage to all other players within a 60 degree cone centered on the original target.\n\n$[!5,6On Heroic difficulty, the Lightning Strike inflicts Nature damage every second for 16 seconds.$]"},
			{id=3027,title="Electrocute",body="Al'Akir channels a bolt of electricity to his current target if he is unable to reach that target with his melee attack, inflicting increasing Nature damage over time. He stops channeling Electrocute when his target returns to melee range."},
			{id=3447,title="Static Shock",body="Al'Akir shocks all players within his melee range, inflicting $87873s1 Nature damage and interrupting any spells cast for $87873d.",difficultyIDs={5,6}},
			{id=3028,title="Stage Two: Your Persistence Angers Me!",body="At 80% health, Al'Akir no longer casts Wind Bursts but continually brings down Acid Rain and spawns Stormlings."},
			{id=3029,title="Squall Line",body="Al'Akir summons a line of wind funnels that move around the platform in a circle. The squalls catch any player that stands within $87855A1 yards, and inflict $87856s2 Nature damage per second for $87856d."},
			{id=3031,title="Electrocute",body="Al'Akir channels a bolt of electricity to his current target if he is unable to reach that target with his melee attack, inflicting increasing Nature damage over time. He stops channeling Electrocute when his target returns to melee range."},
			{id=3032,title="Acid Rain",body="Al'Akir inflicts $88301s1 Nature damage per second to all enemies. The damage dealt increases by $88301s1 every $88290t1 sec."},
			{id=3033,title="Stormling",body="Al'Akir summons a Stormling every 20 seconds. Stormlings inflict $87908s1 Nature damage every second to all players within $87908A1 yards. When Stormlings are killed they cause a Feedback effect on Al'Akir, increasing his damage taken.$[!5,6\n\nOn Heroic difficulty, the Nature damage caused by Stormlings also causes players to take $87908s2% additional Nature damage for 2 sec. This effect stacks from multiple Stormlings.$]"},
			{id=3034,title="Feedback",body="A Stormling's death causes a feedback effect on Al'Akir, increasing the damage he receives by $87904s1%. This effect stacks and lasts $87904d."},
			{id=3035,title="Stage Three: Enough!",body="At 25% health, Al'Akir shatters his platform, tossing all players into the air and granting them the ability to fly. Al'Akir no longer cast Squall Lines, but casts Wind Burst again, along with Lightning, Lightning Cloud and Lightning Rod."},
			{id=3037,title="Eye of the Storm",body="All players can fly at $82724s2% normal movement speed."},
			{id=3036,title="Wind Burst",body="Al'Akir casts a Wind Burst on all players, inflicting $87770s1 Nature damage and knocking them back."},
			{id=3038,title="Lightning",body="Al'Akir continually casts Lightning Bolts at random players, inflicting $89641s1 Nature damage.",difficultyIDs={5,6}},
			{id=3039,title="Lightning Rod",body="Al'Akir electrifies a random player and makes them a Lightning Rod. After $89668d., the player emits lightning at nearby players for $89668d. The lightning inflicts $89667s1 Nature damage every second to all players within 20 yards horizontally and 5 yards vertically."},
			{id=3040,title="Lightning Cloud",body="Al'Akir summons clouds at the altitude of a random player. The Lightning Cloud fills the entire area of that altitude, and after 5 seconds they erupt in an electrical storm, inflicting $89588s1 Nature damage per second to all players within the cloud. A Lightning Cloud lasts 30 seconds."},
		},
	},
