		sections={
			{id=2959,title="Halfus Wyrmbreaker",body="Each week a random three of Halfus's five captured dragonkin awaken. Each awakened dragonkin empowers Halfus and his enslaved Proto-Behemoth with an ability.$[!5,6\n\nOn Heroic difficulty, all five dragonkin awaken and empower Halfus and his enslaved Proto-Behemoth with all possible abilities.$]"},
			{id=2960,title="Malevolent Strikes",body="Halfus's melee strikes wound his current target, reducing healing received by $83908s1% for $83908d. This effect stacks.$[!3,4\n\nThis ability activates when the Slate Dragon awakens.$]"},
			{id=2961,title="Frenzied Assault",body="Halfus permanently increases his attack speed by $83693s1%.$[!3,4\n\nThis ability activates when the Nether Scion awakens.$]"},
			{id=2962,title="Shadow Nova",body="Halfus unleashes dark magic, inflicting $83703s1 Shadow damage and knocking back all enemies within $83703a1 yards.$[!3,4\n\nThis ability activates when the Storm Rider awakens.$]"},
			{id=2963,title="Proto-Behemoth",body="Halfus's enslaved proto-dragon flies nearby, raining down fire upon those who threaten his master.$[!3,4  \n\nLike Halfus, awakened dragonkin empower the Proto-Behemoth with abilities.$]"},
			{id=2964,title="Fireball Barrage",body="The Proto-Behemoth fires rapid volleys of fireballs at random enemy targets.  Each Fireball deals $83734s1 Fire damage within $83734A1 yards of impact.$[!3,4\n\nThis ability activates when the Time Warden awakens.$]"},
			{id=2965,title="Scorching Breath",body="The Proto-Behemoth unleashes waves of flame across the entire platform, dealing $83855s1 Fire damage to all enemies every $83707t1 sec, for $83707d.$[!3,4\n\nThis ability activates when the Orphaned Emerald Whelps awaken.$]"},
			{id=2966,title="Fireball",body="The Proto-Behemoth lobs single fireballs at the location of a random player. When the fireball lands, it inflicts $83734s1 Fire damage to players within $83734A1 yards of the impact. \n\nThis ability is only active when the Time Warden is dormant.",difficultyIDs={1,2,3,4}},
			{id=2967,title="Furious Roar",body="When Halfus reaches 50% remaining health, he periodically emits a Furious Roar. This terrible roar inflicts $83710s1 Physical damage to all players and knocks them to the ground, stunning them for $83710d. Halfus roars three times in rapid succession."},
			{id=2968,title="Imprisoned Dragonkin",body="Halfus has imprisoned a Slate Dragon, a Nether Scion, a Storm Rider, a Time Warden, and a pack of Orphaned Emerald Whelps.  They surround him on his platform, wearing bonds of servitude.  If freed they will each turn on their master and weaken him, but Halfus then dominates the dragonkin and forces them to fight against the players.$[!3,4\n\nIn Normal Difficulty three random dragonkin awaken each week, while the other two slumber.  Only the awakened dragonkin may be freed.$]"},
			{id=2969,title="Nether Scion"},
			{id=2979,title="Nether Blindness",body="Upon being released the Nether Scion shrouds Halfus's eyes with a thick fog, impairing his vision and reducing his chance to hit, attack speed, and damage done by $83611s1%."},
			{id=2970,title="Dragon's Vengeance",body="The Nether Scion curses Halfus as it dies, causing Halfus to take $87683s1% increased damage. This effect stacks."},
			{id=2971,title="Orphaned Emerald Whelps"},
			{id=2980,title="Atrophic Poison",body="Upon being released each Emerald Whelp poisons Halfus's Proto-Behemoth, reducing its damage dealt by $83609s1.  This effect stacks 8 times."},
			{id=2972,title="Dragon's Vengeance",body="The last of the Orphaned Emerald Whelps curses Halfus as it dies, causing Halfus to take $87683s1% increased damage. This effect stacks."},
			{id=2973,title="Slate Dragon"},
			{id=2981,title="Stone Grip",body="Upon being released the Slate Dragon afflicts Halfus with a creeping paralysis, causing him to occasionally petrify for $84030d. While petrified, Halfus cannot move or attack and players inflict $84591s2% more damage to Halfus."},
			{id=2974,title="Dragon's Vengeance",body="The Slate Dragon curses Halfus as it dies, causing Halfus to take $87683s1% increased damage. This effect stacks."},
			{id=2975,title="Storm Rider"},
			{id=2982,title="Cyclone Winds",body="Upon being released the Storm Rider envelops Halfus in a cyclone, slowing his casting speed by $84092s1%."},
			{id=2976,title="Dragon's Vengeance",body="The Storm Rider curses Halfus as it dies, causing Halfus to take $87683s1% increased damage. This effect stacks."},
			{id=2977,title="Time Warden"},
			{id=2983,title="Time Dilation",body="Upon being released the Time Warden warps the flow of time around Halfus's Proto-Behemoth, reducing the velocity of its deadly fireballs."},
			{id=2978,title="Dragon's Vengeance",body="The Time Warden curses Halfus as it dies, causing Halfus to take $87683s1% increased damage. This effect stacks."},
		},
	},
	[157]={
		encounterID=157,
		instanceID=72,
		order=2,
		name="Theralion and Valiona",
		lore="Magically aged to adulthood, Valiona and Theralion were to be paragons among a new clutch of twilight dragons, leading their brood in scouring Azeroth of life. Instead, they waste their incredible powers constantly bickering and fighting each other.",
		dungeonEncounterID=1032,
		uiMapID=294,
		pin={x=0.5399,y=0.7844},
		difficultyIDs={1,2,3,4,5,6},
		npcIDs={45992,45993},
		displayIDs={34812,34813},
		loot={
			{itemID=65091,diffs={5,6},faction=-1},
			{itemID=65092,diffs={5,6},faction=-1},
			{itemID=65093,diffs={5,6},faction=-1},
			{itemID=65094,diffs={5,6},faction=-1},
