		name="Ascendant Council",
		lore="As the most powerful Twilight's Hammer cultists to be twisted into elemental beings, the Ascendant Council members have long forgotten their existence as mere mortals. From their wicked sanctum, they oversee the selection of new ascension candidates.",
		dungeonEncounterID=1028,
		uiMapID=295,
		pin={x=0.4251,y=0.4551},
