		sections={
			{id=3165,title="Corrupted Blood",body="Exposure to several of Cho'gall's abilities increases a player's Corruption level. For each point of Corruption they have, players suffer $81701s1% additional damage from Cho'gall's Corruption of the Old God ability."},
			{id=3222,title="Corruption: Accelerated",body="When Corrupted Blood reaches 25%, a player gains Corruption: Accelerated, which rapidly increases their Corruption level."},
			{id=3223,title="Corruption: Sickness",body="When Corrupted Blood reaches 50%, players periodically become violently ill. They vomit and inflict $81831s1 Shadow damage to players within a $81831A1 yard long 20 degree cone in front of them. Players hit by this vile spew suffer increased Corruption."},
			{id=3224,title="Corruption: Malformation",body="When Corrupted Blood reaches 75%, the corruption is so thorough that a tentacle Malformation erupts from a player's back. The tentacle periodically casts Shadow Bolts at the player's allies, inflicting $82151s1 Shadow damage."},
			{id=3225,title="Corruption: Absolute",body="When Corrupted Blood reaches 100%, players fully transform into faceless horrors. While in this state players cannot be healed, but inflict $82170s2% additional damage and cast spells instantly."},
			{id=3154,title="Stage One: Chaos Comes!"},
			{id=3155,title="Conversion",body="Cho'gall beckons to the weak of mind, causing random players to abandon their loyalties and begin to Worship Cho'gall. Worshipping Cho'gall grants him one application of Twisted Devotion every $91317t1 sec."},
			{id=3209,title="Twisted Devotion",body="Cho'gall gains strength from his converted followers, increasing his damage dealt by $91331s1% for $91331d.  This effect stacks."},
			{id=3210,title="Fury of Cho'gall",body="Cho'gall blasts his current target, inflicting $82523s1 Shadow and $82518s1 Physical damage, and increasing Physical and Shadow damage taken by $82523s2% for $82523d."},
			{id=3156,title="Flame's Orders",body="Cho'gall calls forth a Fire elemental and absorbs the elemental into his Twilight Hammer, empowering it with Flaming Destruction.$[!5,6\n\nOn Heroic difficulty Cho'gall gains one additional stack of Flaming Destruction for each 10% health remaining on the elemental when it is absorbed.$]"},
			{id=3157,title="Flaming Destruction",body="While Flame's Orders empowers Cho'gall's hammer, his melee attacks inflict $81527s1 additional Fire damage to his current target and splashes molten fire that creates a burning Blaze nearby."},
			{id=3211,title="Blaze",body="A $81538A1 yard radius pool of burning flames inflicts $81538s1 Fire damage every $81536t1 sec on players standing within the fire. The Blaze lasts $81532d."},
			{id=3158,title="Shadow's Orders",body="Cho'gall calls forth a Shadow elemental and absorbs the elemental into his Twilight Hammer, imbuing it with Empowered Shadows.$[!5,6\n\nOn Heroic Difficulty Cho'gall gains one stack of Empowered Shadows for each 10% health remaining on the elemental when it is absorbed.$]"},
			{id=3212,title="Empowered Shadows",body="While Shadow's Orders empowers Cho'gall's hammer, it emits bursts of nether power every $81572t1 sec. The hammer deals $81571s1 Shadow damage to players within $81571A1 yards."},
			{id=3160,title="Summon Corrupting Adherent",body="Cho'gall summons a Corrupting Adherent from one of twilight portals at the sides of the room.$[!6\n\nOn 25-player Heroic difficulty, Cho'gall activates both portals, summoning two Corrupting Adherents simultaneously.$]"},
			{id=3161,title="Corrupting Adherent",body="Cho'gall summons these faceless minions of the Old Gods to hasten the doom of his foes."},
			{id=3162,title="Depravity",body="The Corrupting Adherent inflicts $81713s1 Shadow damage to players within $81713A1 yards, raising their Corruption levels significantly."},
			{id=3213,title="Corrupting Crash",body="The Corrupting Adherent lobs a shadow missile at the ground beneath a random player, inflicting $81689s1 Shadow damage to all players within $81689a1 yards of the impact. Players hit by the Corrupting Crash gain Corruption."},
			{id=3214,title="Spilled Blood of the Old God",body="When Cho'gall casts Fester Blood, corpses of Corrupting Adherents dissolve into pools of black bile. Any players in contact with these pools suffer $81761s1 Shadow damage per $81757t1 sec. and gain Corruption."},
			{id=3163,title="Fester Blood",body="Cho'gall festers the blood of all Corrupting Adherents, causing pools of Spilled Blood of the Old God to form into animated oozes.  Fester Blood also causes the dark blood of any living Corrupting Adherents to boil, causing the Festering Blood effect."},
			{id=3215,title="Festering Blood",body="When Cho'gall uses Fester Blood, the dark blood of any living Corrupting Adherents sprays out from their bodies, inflicting $82919s1 Shadow damage every $82914t1 sec to all players within $82919A1 yards.  Players damaged by this ability will gain Corruption."},
			{id=3216,title="Blood of the Old God",body="The Corrupting Adherents' blood congeals into numerous vile oozes, each of which fixates on a random player and moves towards them. The animated Blood of the Old God raises the Corruption level of any target they melee."},
			{id=3164,title="Stage Two: Come, Infinite Night!",body="When Cho'gall reaches 25% health, he calls upon the full powers of the Old Gods. He absorbs the dark energies of any remaining Corrupting Adherents and pools of Spilled Blood of the Old God, then transforms himself into a twisted creature."},
			{id=3217,title="Fury of Cho'gall",body="Cho'gall blasts his current target, inflicting $82523s1 Shadow and $82518s1 Physical damage, and increasing Physical and Shadow damage taken by $82523s2% for $82523d."},
			{id=3218,title="Corruption of the Old God",body="Cho'gall fills the room with tendrils of shadowy corruption, inflicting $82363s1 Shadow damage every $82361t1 sec to all players and gradually increasing their Corruption level. Players suffer $81701s1% additional damage from Corruption of the Old God for each point of their Corruption."},
			{id=3219,title="Darkened Creations",body="Cho'gall causes tentacles to erupt from inky clouds on the ground."},
			{id=3220,title="Darkened Creation",body="Darkened Creations continually try to channel Debilitating Beam on a random player."},
			{id=3221,title="Debilitating Beam",body="Debilitating Beam reduces a target's healing and damage done by $82411s2% and inflicts $82411s1 Shadow damage every $82411t1 sec for $82411d.$[!5,6\n\nOn Heroic difficulty, Debilitating Beam also causes Corrupted Blood.$]"},
		},
	},
	[168]={
		encounterID=168,
		instanceID=72,
		order=5,
		name="Sinestra",
		lore="Originally Deathwing's prime consort, Sinestra created the first twilight dragons, but was later obliterated by one of her terrifying creations. Now a ravaged husk reanimated by insidious magic, Sinestra oversees the creation of new twilight clutches.",
		dungeonEncounterID=1082,
		uiMapID=296,
		pin={x=0.49,y=0.3428},
		difficultyIDs={5,6},
		npcIDs={45213},
		displayIDs={34335},
		loot={
			{itemID=60226,diffs={5,6},faction=-1},
			{itemID=60227,diffs={5,6},faction=-1},
			{itemID=60228,diffs={5,6},faction=-1},
			{itemID=60229,diffs={5,6},faction=-1},
			{itemID=60230,diffs={5,6},faction=-1},
			{itemID=60231,diffs={5,6},faction=-1},
			{itemID=60232,diffs={5,6},faction=-1},
			{itemID=60233,diffs={5,6},faction=-1},
			{itemID=60234,diffs={5,6},faction=-1},
			{itemID=60235,diffs={5,6},faction=-1},
			{itemID=60236,diffs={5,6},faction=-1},
			{itemID=60237,diffs={5,6},faction=-1},
			{itemID=60238,diffs={5,6},faction=-1},
		},
		sections={
			{id=3226,title="Stage One: I Will Deal With You Myself!",body="At the outset of the battle, Sinestra is weakened from past battles and from nurturing the Twilight brood. She begins with only 60% of her maximum health, and her damage dealt is reduced by by $89350s1%.",difficultyIDs={5,6}},
			{id=3227,title="Wrack",body="Sinestra causes a random player to suffer Shadow damage every $89421t1 sec. for $89421d. with the damage taken increasing rapidly. When a player dispels Wrack, it bounces to two nearby allies of the afflicted player. Wrack retains its remaining duration but returns to its original damage values.",difficultyIDs={5,6}},
			{id=3228,title="Flame Breath",body="Sinestra unleashes a torrent of flame that sweeps across her platform, inflicting $90125s1 Fire damage to all enemies.",difficultyIDs={5,6}},
			{id=3229,title="Twilight Slicer",body="Sinestra summons two shadowy orbs, each of which fixates on a player and begins to pursue that player. These spheres are linked together by a cutting beam of pure twilight energy that inflicts $92852s1 Shadow damage per $92851t1 sec. to any player who comes into contact with the beam.\n\nEach sphere also pulses twilight energy, inflicting $92958s1 Shadow damage every $92957t1 sec in a $92958A1 yard radius. The orbs dissipate after $92957d.",difficultyIDs={5,6}},
			{id=3230,title="Twilight Blast",body="When Sinestra cannot reach anyone in melee range, she blasts an enemy for $89280s1 Shadow damage.",difficultyIDs={5,6}},
			{id=3231,title="Twilight Whelps",body="Sinestra periodically calls forth a set of five Twilight Whelps to attack intruders.",difficultyIDs={5,6}},
			{id=3232,title="Twilight Spit",body="The Twilight Whelps spit shadowy bile on their target, inflicting $89299s1 Shadow damage and increasing the target's Shadow damage taken by $89299s2%. This effect stacks.",difficultyIDs={5,6}},
			{id=3233,title="Twilight Essence",body="When a Twilight Whelp dies, the essence instilled in it by Sinestra leaks out, forming a bubbling puddle beneath its corpse. If this essence touches any other dead Twilight Whelp, that Whelp reanimates. Each pool of Twilight Essence expands over time. The pools inflict $88146s2 Shadow damage every $89284t1 sec.",difficultyIDs={5,6}},
			{id=3234,title="Stage Two: I Tire of This!",body="When Sinestra is brought to 30% health, she draws upon ambient energy to restore her power and erects a shield to protect herself.",difficultyIDs={5,6}},
			{id=3235,title="A Clash of Flame and Twilight",body="The red dragon Caelestrasz, Calen in his humanoid form, comes to the party's aid and engages in a magical duel with Sinestra. The duelist with the most mana gains the upper hand.",difficultyIDs={5,6}},
			{id=3236,title="Pyrrhic Focus",body="Calen burns his own health reserves to restore his mana. His focus also increases healing done to Calen by $87323s2%.",difficultyIDs={5,6}},
			{id=3237,title="Mana Barrier",body="A powerful barrier envelops Sinestra, continually replenishing any lost health at the expense of her mana.",difficultyIDs={5,6}},
			{id=3238,title="Pulsing Twilight Egg",body="Sinestra has stored vast reserves of twilight energy in these massive eggs.",difficultyIDs={5,6}},
			{id=3308,title="Twilight Carapace",body="The Pulsing Twilight Eggs are normally impervious to all damage. In moments of dire need, Sinestra directly siphons from the eggs and causes their Twilight Carapace to drop temporarily.",difficultyIDs={5,6}},
			{id=3239,title="Twilight Spitecaller",body="These twilight dragonkin periodically stream into the room during the clash between Calen and Sinestra.",difficultyIDs={5,6}},
			{id=3240,title="Unleash Essence",body="The Twilight Spitecaller releases a torrent of twilight energy that afflicts all nearby enemies, inflicting damage equal to $90028s1% of each target's maximum health every $90028t1 sec.  Conventional interrupts cannot prevent the casting of the spell, but other effects that cause loss of control may be effective.",difficultyIDs={5,6}},
			{id=3241,title="Indomitable",body="If a Twilight Spitecaller is incapacitated for more than a brief period of time, it regains control through a surge of sheer will. The Spitecaller becomes immune to all bonds and restraints until a player removes this effect, and inflicts $90045s2 Shadow damage and knocks back players within $90045A2 yards.",difficultyIDs={5,6}},
			{id=3242,title="Twilight Drake",body="Twilight Drakes swoop in from the sides of the cavern during the clash between Calen and Sinestra.",difficultyIDs={5,6}},
			{id=3243,title="Twilight Breath",body="The Drake's breath inflicts $90083s1 Shadow damage in a $90083a1 yard 60 degree cone in front of it.",difficultyIDs={5,6}},
			{id=3244,title="Absorb Essence",body="If a Twilight Drake comes into contact with a pool of Twilight Essence, it siphons that energy and causes the pool to shrink and eventually vanish entirely. Each charge of Essence absorbed increases the Drake's damage by $90107s1%, and its health by $90107s2%. This effect stacks.",difficultyIDs={5,6}},
			{id=3245,title="Stage Three: Now Die!",body="Once the players destroy the Pulsing Twilight Eggs, Sinestra brings her magical duel with Calen to an end and attacks the players with her full fury. Empowered by the twilight eggs from which she reclaims her siphoned energy, Sinestra no longer deals reduced damage.",difficultyIDs={5,6}},
			{id=3246,title="Essence of the Red",body="Calen bestows a blessing of Alexstrasza upon the raid, granting all players $87946s2% melee, ranged, and spell haste, and causing them to regain $87946s1% of their maximum mana per second. Essence of the Red lasts for $87946d.",difficultyIDs={5,6}},
			{id=3247,title="Wrack",body="Sinestra causes a random player to suffer Shadow damage every $89421t1 sec. for $89421d. with the damage taken increasing rapidly. When a player dispels Wrack, it bounces to two nearby allies of the afflicted player. Wrack retains its remaining duration but returns to its original damage values.\n\nSuccessfully dispelling Wrack instantly finishes the cooldown of the caster's single-target Magic dispel abilities.",difficultyIDs={5,6}},
			{id=3248,title="Flame Breath",body="Sinestra unleashes a torrent of flame that sweeps across her platform, dealing $90125s1 Fire damage to all enemies.",difficultyIDs={5,6}},
			{id=3249,title="Twilight Slicer",body="Sinestra summons two shadowy orbs, each of which fixates on a player and begins to pursue that player. These spheres are linked together by a cutting beam of pure twilight energy that inflicts $92852s1 Shadow damage per $92851t1 sec. to any player who comes into contact with the beam.\n\nEach sphere also pulses twilight energy, inflicting $92958s1 Shadow damage every $92957t1 sec in a $92958A1 yard radius. The orbs dissipate after $92957d.",difficultyIDs={5,6}},
			{id=3250,title="Twilight Blast",body="When Sinestra cannot reach anyone in melee range, she blasts an enemy for $89280s1 Shadow damage.",difficultyIDs={5,6}},
			{id=3251,title="Twilight Whelps",body="Sinestra periodically calls forth a set of five Twilight Whelps to attack intruders.",difficultyIDs={5,6}},
			{id=3252,title="Twilight Spit",body="The Twilight Whelps spit shadowy bile on their target, inflicting $89299s1 Shadow damage and increasing the target's Shadow damage taken by $89299s2%. This effect stacks.",difficultyIDs={5,6}},
			{id=3253,title="Twilight Essence",body="When a Twilight Whelp dies, the essence instilled in it by Sinestra leaks out, forming a bubbling puddle beneath its corpse. If this essence touches any other dead Twilight Whelp, that Whelp reanimates. Each pool of Twilight Essence expands over time. The pools inflict $88146s2 Shadow damage every $89284t1 sec.",difficultyIDs={5,6}},
			{id=3352,title="Heroic Difficulty Only",body="Sinestra is only available in Heroic Difficulty.",difficultyIDs={1,2,3,4}},
		},
	},
