		sections={
			{id=3193,title="Primary Defense Matrix",body="The four dwarven golems share a health pool and two are active at any given time. When a golem activates, it possesses 100 energy to use for its abilities. Once the golem's energy reaches 50, it gains a defensive shield and a new golem activates. Once the golem's energy reaches 0, the golem deactivates and another golem activates."},
			{id=3194,title="Arcanotron"},
			{id=3195,title="Power Generator",body="Arcanotron summons a Power Generator under a random player. The field increases the damage dealt by $79629s1% for all units within $79629a1 yards and restores $79629s2 mana every $79628t1 seconds. The Power Generator lasts $79628d."},
			{id=3196,title="Arcane Annihilator",body="Arcanotron blasts a random player for $79710s1 Arcane damage.$[!4,6\n\nIn 25-player raids Arcanotron blasts three random players.$]"},
			{id=3197,title="Power Conversion",body="Arcanotron's shield converts damage taken into Converted Power, which provides additional magic damage and cast speed."},
			{id=3198,title="Converted Power",body="Damage done to Arcanotron's Power Conversion shield grants him $79735s1% additional Arcane damage and increases his spell haste by $79735s2% for $79735d. This effect stacks."},
			{id=3199,title="Overcharged Power Generator",body="Lord Victor Nefarius converts a Power Generator into an Overcharged Power Generator. The field increases the damage dealt by $91858s1% for all units within $91858a1 yards and restores $91858s2 mana every $91857t1 seconds.\n\nAn Overcharged Power Generator grows in size until it explodes, triggering Arcane Blowback.",difficultyIDs={5,6}},
			{id=3200,title="Arcane Blowback",body="An Overcharged Power Generator explodes, inflicting $91879s1 Arcane damage to players within $91879A1 yards.",difficultyIDs={5,6}},
			{id=3201,title="Electron"},
			{id=3202,title="Lightning Conductor",body="Electron designates a random player as a Lightning Conductor, causing them to inflict $79889s1 Nature damage to allies within $79889A1 yards every $79888t1 sec., for $79888d."},
			{id=3203,title="Electrical Discharge",body="Electron inflicts $79879s1 Nature damage to up to 3 targets within 8 yards. The damage inflicted increases with each jump."},
			{id=3204,title="Unstable Shield",body="Dealing damage to Electron's shield causes a Static Shock at a nearby player's location, inflicting $79912s1 Nature damage to players within $79912A1 yards of the target."},
			{id=3205,title="Shadow Infusion",body="Lord Victor Nefarius corrupts the Lightning Conductor, transforming the target into a Shadow Conductor.  Shadow Conductor causes Shadow damage to all nearby allies every 2 sec., with the magnitude of the damage increasing with greater distance from the Shadow Infused player.",difficultyIDs={5,6}},
			{id=3207,title="Magmatron"},
			{id=3264,title="Incineration Security Measure",body="Magmatron strikes everyone in the room for $79035s1 Fire damage every $79023t1 sec. for $79023d."},
			{id=3265,title="Acquiring Target",body="Magmatron acquires a random player as a target for his Flamethrower ability. After $79501d. Magmatron channels his Flamethrower on the target, inflicting $79504s1 Fire damage every $79505t1 sec. to all players in front of him for $79505d."},
			{id=3266,title="Flamethrower",body="Magmatron inflicts $79504s1 Fire damage every $79505t1 sec. to all enemies in front of him for $79505d."},
			{id=3267,title="Encasing Shadows",body="Lord Victor Nefarius causes shadows to bind the feet of the Acquired Target, preventing movement until the Flamethrower finishes channeling.",difficultyIDs={5,6}},
			{id=3268,title="Barrier",body="Magmatron's shield absorbs $79582s1 damage. If the Barrier breaks, it releases a gale of flame, inflicting $79617s1 Fire damage to all players."},
			{id=3208,title="Toxitron"},
			{id=3269,title="Chemical Bomb",body="Toxitron fires a Chemical Bomb at a random player, creating a Chemical Cloud at their location. The cloud increases the damage taken by any unit in the cloud."},
			{id=3270,title="Chemical Cloud",body="Toxitron's Chemical Cloud increases the damage taken by any unit in the cloud by $80161s1%. $[!5,6\n\nThe Chemical Cloud also inflicts $80161s2 Nature damage every $80162t1 seconds.$]"},
			{id=3271,title="Poison Protocol",body="Toxitron's Poison Protocol creates a Poison Bomb every $80053t1 seconds. Each Poison Bomb fixates on a random player. A Poison Bomb explodes when it reaches melee range of its target."},
			{id=3272,title="Poison Bomb",body="The Poison Bombs created by Toxitron's Poison Protocol each fixate on a random player. A Poison Bomb explodes and creates a Poison Puddle when it reaches melee range of its target."},
			{id=3273,title="Poison Puddle",body="Poison Bombs create $80097A1 yard radius Poison Puddles when they explode. The Poison Puddle inflicts $80097s1 Nature damage every $80095t1 sec. on any player standing within the puddle."},
			{id=3274,title="Poison Soaked Shell",body="Dealing damage to Toxitron's shield inflicts Soaked in Poison on the damaging player."},
			{id=3454,title="Soaked in Poison",body="Soaked in Poison inflicts $80011s2 Nature damage every $80011t2 sec. This effect stacks, but dispelling this poison once removes all stacks.\n\nWhen a player attacks or uses a spell or ability, they expunge the poison on their target."},
			{id=3456,title="Expunge Poison",body="The poison soaked player inflicts $80014s1 Nature damage on their target."},
			{id=3275,title="Grip of Death",body="Lord Victor Nefarius sometimes teleports to the center of a Chemical Cloud and casts Grip of Death, pulling all players into the cloud.",difficultyIDs={5,6}},
		},
	},
	[170]={
		encounterID=170,
		instanceID=73,
		order=2,
		name="Magmaw",
		lore="Magmaw is a colossal lava worm summoned from the Firelands centuries ago by Ragnaros' Dark Iron servitors. Nefarian largely considers Magmaw a worrisome pest, but has grown fond of feeding the beast his failed experiments... and servants.",
		dungeonEncounterID=1024,
		uiMapID=285,
		pin={x=0.2754,y=0.5749},
		difficultyIDs={1,2,3,4,5,6},
		npcIDs={41570},
		displayIDs={37993},
		loot={
