		sections={
			{id=3310,title="Magma Spit",body="Magmaw spits a volley of magma at three random players, inflicting $78359s1 Fire damage to each player.$[!4,6\n\nIn 25 player raids Magmaw spits at eight random players.$]"},
			{id=3311,title="Pillar of Flame",body="Magmaw barrages the ground beneath a random player's feet with globs of roiling magma. The impacts sunder the ground, causing eruptions that knock players within $77971A1 yards high into the air and inflicting $77971s1 Fire damage every $77970t1 sec. The impacts also spawn multiple Lava Parasites."},
			{id=3312,title="Lava Parasite",body="These slow moving creatures will burrow into the warm flesh of players when they attack, infecting their new host."},
			{id=3313,title="Parasitic Infection",body="When a Lava Parasite burrows into the flesh of a player, the Lava Parasite inflicts $78941s1 damage every $78941t1 sec. for $78941d. After the infection runs its course, the player vomits up the Parasite. It then begins to search for a new host."},
			{id=3316,title="Lava Spew",body="Magmaw spews a stream of molten lava across all players, inflicting $77690s1 Fire damage every $77689t1 sec for $77689d."},
			{id=3317,title="Molten Tantrum",body="If Magmaw is ever unable to reach an enemy with his melee attack, he enters a frenzy. Magmaw then launches Magma Spit at all players and increases his Fire damage dealt by $78403s1% for $78403d. This effect stacks."},
			{id=3314,title="Mangle",body="Magmaw picks up his current target in his jaws, then bites down. The crushing force inflicts $89773s1 damage every $89773t1 sec.  Magmaw crushes his target severely after $89773d.  Impaling Magmaw causes him to release his grasp on the target."},
			{id=3315,title="Sweltering Armor",body="Magmaw's fiery jaws melt the armor of the player targeted by Mangle, reducing the player's armor by $78199s1% for $78199d."},
			{id=3318,title="Massive Crash",body="Magmaw brings his entire body smashing down on one half of the room, inflicting $88287s1 damage and stuns all players caught beneath him for $88287d. The Massive Crash also briefly stuns Magmaw, allowing two players to leap onto his pincers."},
			{id=3319,title="Lava Worm Wrangling",body="Immediately after Magmaw performs Massive Crash, a window of opportunity exists where two players can leap onto his pincers. From that location they can attach chains to the spike protruding from the ground in front of the worm, and then reel Magmaw onto the spike."},
			{id=3320,title="Launch Hook",body="The players hanging onto Magmaw's pincers can launch a hook at the spike in front of the worm. If the hook connects, it chains Magmaw to the spike for $77917d. Magmaw will break free from a single connecting chain, but if a player connects a second chain to the spike then the players reel the chains in and impale Magmaw on the spike."},
			{id=3321,title="Point of Vulnerability",body="When Magmaw is impaled on the spike, players can attack his exposed and unarmored head. Attacking the exposed head increases the damage dealt to Magmaw by $79011s1%.  Magmaw frees himself from the spike after $77907d."},
			{id=3322,title="Lord Victor Nefarius",body="On Heroic Difficulty Lord Nefarius arrives to observe the adventurers contend with his pet and thwart their efforts.",difficultyIDs={5,6}},
			{id=3323,title="Blazing Inferno",body="Lord Nefarius calls down a meteor of bone and fire at the ground beneath a random player. The meteor inflicts $92154s2 Fire damage to players in a $92154A2 yard radius and knocks them down. The explosion creates a Blazing Bone Construct, and sparks the Ignition of fast-moving flames in a spiral around the point of impact.",difficultyIDs={5,6}},
			{id=3324,title="Ignition",body="The Blazing Inferno creates moving patches of flame that swirl around the point of impact, inflicting $92134s1 Fire damage every $92131t1 sec to all players within $92134A1 yards of them. The Ignition flames dissipate after $92129d.",difficultyIDs={5,6}},
			{id=3325,title="Blazing Bone Construct",body="Lord Nefarius's Blazing Inferno creates a single flaming skeletal construct.",difficultyIDs={5,6}},
			{id=3326,title="Fiery Slash",body="The construct slashes at an enemy with its fiery claws, dealing $92144s1% of normal melee damage as Fire damage.",difficultyIDs={5,6}},
			{id=3327,title="Armageddon",body="When a Blazing Bone Construct reaches 20% remaining health, it prepares to self-destruct. The Blazing Bone Construct then explodes in an Armageddon, inflicting $92182s2 Fire damage to all players.",difficultyIDs={5,6}},
			{id=3328,title="Shadow Breath",body="When Magmaw reaches 30% remaining health, Lord Nefarius begins to directly attack the players. He launches volleys of shadowy flame at random players. The Shadow Breath inflicts $92173s1 Shadow damage to all players within $92173A1 yards of his target.",difficultyIDs={5,6}},
		},
	},
	[171]={
		encounterID=171,
		instanceID=73,
		order=3,
		name="Atramedes",
		lore="Atramedes, or Experiment 25463-D, is a failed attempt to bestow enhanced senses on a black dragon whelp. The toxic salve applied to the broodling robbed him of sight, forcing him to rely on sound and smell for survival. A tragic story... if Atramedes weren't so evil.",
		dungeonEncounterID=1022,
		uiMapID=286,
		pin={x=0.475,y=0.3278},
		difficultyIDs={1,2,3,4,5,6},
		npcIDs={41442},
		displayIDs={34547},
		loot={
			{itemID=65056,diffs={5,6},faction=-1},
			{itemID=65058,diffs={5,6},faction=-1},
			{itemID=65059,diffs={5,6},faction=-1},
			{itemID=65060,diffs={5,6},faction=-1},
