			{itemID=59324,diffs={1,2,3,4},faction=-1},
			{itemID=65052,diffs={5,6},faction=-1},
			{itemID=59325,diffs={1,2,3,4},faction=-1},
			{itemID=65053,diffs={5,6},faction=-1},
			{itemID=59326,diffs={1,2,3,4},faction=-1},
			{itemID=65054,diffs={5,6},faction=-1},
			{itemID=59327,diffs={1,2,3,4},faction=-1},
			{itemID=65055,diffs={5,6},faction=-1},
		},
		sections={
			{id=3072,title="Sound",body="Atramedes is blind and hunts based on sound. Players begin the battle with 0 Sound and gain Sound when taking damage. Atramedes channels Devastation on targets with 100 Sound and quickly kills them.\n\nUsing an Ancient Dwarven Shield resets the Sound on all players."},
			{id=3073,title="Ancient Dwarven Shields",body="Ten Ancient Dwarven Shields are positioned around the room. Any player can strike one of the shields and cause a Resonating Clash. This interrupts Atramedes' casting, resets the Sound on every player to zero, and gives Atramedes a case of Vertigo. When Atramedes recovers from Vertigo, he destroys the shield.$[!5,6\n\nIn Heroic Difficulty Lord Nefarius destroys an additional shield whenever Atramedes destroys one.$]"},
			{id=3074,title="Resonating Clash",body="The sound resonating from the Ancient Dwarven Shield interrupts Atramedes' casting.\n\nWhile Airborne, Atramedes switches the target of his Roaring Flame Breath to the player who used the Ancient Dwarven Shield."},
			{id=3075,title="Vertigo",body="The Resonating Clash places Atramedes into a state of Vertigo, increasing damage taken by $77717s1% for $77717d."},
			{id=3061,title="Grounded Abilities",body="Atramedes begins the fight on the ground."},
			{id=3076,title="Sonar Pulse",body="Atramedes periodically sends out discs of sonic energy to locate players. Players struck by a Sonar Pulse gain $77675s1 Sound. $[!5,6\n\nOn Heroic Difficulty a Sonar Pulse also inflicts $77675s2 Arcane damage.$]"},
			{id=3077,title="Modulation",body="Atramedes casts Modulation, inflicting $77612s1 Shadow damage.$[!5,6\n\nModulation inflicts $77612s2 additional Sound, and the damage inflicted on a player increases with higher Sound levels.$]"},
			{id=3078,title="Sonic Breath",body="Atramedes tracks on a random player, breathing fire as he turns towards that player. Sonic Flame inflicts $78100s1 Fire damage to all players in its path and adds $78100s2 Sound."},
			{id=3079,title="Searing Flames",body="Atramedes channels and fills the room with flames. The flames inflict $77982s1 Fire damage every $77974t1 sec. and increases Fire damage taken by $77982s2% for $77974d. The damage increases by 2% for every point of Sound on the target. Resonating Clash interrupts the channeling of Searing Flames.\n\nSearing Flames leaves behind patches of Roaring Flames on the ground for $78023d."},
			{id=3080,title="Roaring Flames",body="Searing Flames produces patches of Roaring Flame on the ground. Players crossing the Roaring Flames take $78023s1 Fire damage and an additional $78023s2 Fire damage every $78023t2 sec for $78023d. Roaring Flames also adds 5 Sound."},
			{id=3455,title="Devastation",body="Atramedes channels Devastation on all players with 100 sound, inflicting $78868s1 Fire damage every $78898t1 second."},
			{id=3081,title="Airborne Abilities",body="Atramedes periodically flies up into the air during the fight, raining destruction down on his enemies from above."},
			{id=3086,title="Roaring Flame Breath",body="Atramedes breathes a gout of flame that follows a random player around the room. The Roaring Flame Breath inflicts $78555s1 Fire damage and leaves Roaring Flames in its wake. The movement of the breath speeds up over time.\n\nA Resonating Clash temporarily halts the progress of breath, but Atramedes then retargets the flames on a player that used the Ancient Dwarven Shield."},
			{id=3087,title="Roaring Flames",body="Roaring Flame Breath produces patches of Roaring Flame on the ground. Players crossing the Roaring Flames take $78023s1 Fire damage and an additional $78023s2 Fire damage every $78023t2 sec for $78023d. Roaring Flames also adds 5 Sound."},
			{id=3085,title="Sonar Bomb",body="Atramedes launches Sonar Bombs at the locations of random players. The impact of the Sonar Bomb inflicts $92553s1 Arcane damage to players within $92553A1 yards of the targeted location and increases their Sound by $92553s2."},
			{id=3088,title="Sonic Fireball",body="Atramedes launches Sonic Fireballs at the areas where his Sonar Bombs landed. Sonic Fireballs inflict $78115s1 Fire damage to all enemies within $78115A1 yards of the target."},
			{id=3082,title="Obnoxious Fiend",body="Lord Victor Nefarius meddles in the fight, randomly opening portals and allowing Obnoxious Fiends to enter the fray. Each Obnoxious Fiend jumps on the back of a random player and tries to increase that player's Sound.",difficultyIDs={5,6}},
			{id=3083,title="Phase Shift",body="Obnoxious Fiends are immune to spells when not on a player's back.",difficultyIDs={5,6}},
			{id=3084,title="Obnoxious",body="When an Obnoxious Fiend jumps on a player's back, it casts Obnoxious to increase that player's Sound by 10.",difficultyIDs={5,6}},
		},
	},
