		sections={
			{id=2929,title="Stage One: Mustn't Fail Again!",body="Periodically, Maloriak throws various vials into his cauldron, causing different effects. The first two Vials will be Red then Blue or Blue then Red, followed by Green, then the cycle repeats."},
			{id=2930,title="Arcane Storm",body="Maloriak channels an Arcane Storm inflicting $77908s1 Arcane damage per second for $77896d. to all players."},
			{id=2934,title="Remedy",body="Maloriak heals himself for $77912s1 health and generates $77912s2 mana per second for $77912d. The amount healed increases by $77912s1 per second."},
			{id=2935,title="Red Vial",body="Maloriak throws a Red Vial into his cauldron, giving him flaming breath. The effects of the Red Vial last for 40 seconds."},
			{id=2936,title="Consuming Flames",body="Maloriak ignites a random player in flames, inflicting $77786s1 Fire damage per second for $77786d. Any magic damage taken by the player while ignited increases the damage Consuming Magic deals by 50% of the magic damage taken."},
			{id=2937,title="Scorching Blast",body="Maloriak breathes fire, inflicting $77679s1 Fire damage divided among all targets in a 70 degree cone up to $77679a1 yards in front of him."},
			{id=2931,title="Release Aberrations",body="Maloriak releases 3 Aberrations from their growth chambers. These Aberrations then attack the players."},
			{id=2932,title="Aberration",body="These failed experiments use a Growth Catalyst to increase the damage of nearby allies and reduce their damage taken."},
			{id=2933,title="Growth Catalyst",body="Each Aberration increases the damage of other Aberrations within $77987A1 yards by $77987s1% and reduces their damage taken by $77987s2%. This effect stacks, and also affects Maloriak and Prime Subjects."},
			{id=2938,title="Blue Vial",body="Maloriak throws a Blue Vial into his cauldron, granting him freezing magic. The effects of the Blue Vial last for 40 seconds."},
			{id=2939,title="Biting Chill",body="Maloriak targets a random player with a ring of frost, which inflicts $77763s1 Frost damage to the player and any other players within $77763A1 yards. The ring lasts $77760d."},
			{id=2940,title="Flash Freeze",body="Maloriak causes the area around a random player to suddenly become freezing cold, inflicting $77699s2 Frost damage to all players within $77699A1 yards of the target and encasing them in solid ice for $77699d. \n\nWhen the ice breaks, the targets are released but the breaking ice inflicts an additional $77715s1 Frost damage to all players within $77715A1 yards around that target, breaking all ice in that area."},
			{id=2956,title="Release Aberrations",body="Maloriak releases 3 Aberrations from their growth chambers. These Aberrations then attack the players."},
			{id=2957,title="Aberration",body="These failed experiments use a Growth Catalyst to increase the damage of nearby allies and reduce their damage taken."},
			{id=2958,title="Growth Catalyst",body="Each Aberration increases the damage of other Aberrations within $77987A1 yards by $77987s1% and reduces their damage taken by $77987s2%. This effect stacks, and also affects Maloriak and Prime Subjects."},
			{id=2941,title="Green Vial",body="Maloriak throws a Green Vial into his cauldron. The mixture explodes and cancels the Growth Catalyst on the Aberrations. The effects of the Green Vial last for 40 seconds."},
			{id=2942,title="Debilitating Slime",body="Slime sprays out from the cauldron, coating every unit in the room. The slime increases all damage taken by $77615s1% and temporarily suppresses any Growth Catalysts. Lasts $77615d."},
			{id=2943,title="Dark Magic",body="Lord Victor Nefarius throws Dark Magic into the cauldron, causing Vile Swill to spew from the cauldron. The effects of the Dark Magic last for 90 seconds. The Dark Magic also grants Maloriak immunity to Taunt effects.",difficultyIDs={5,6}},
			{id=2945,title="Engulfing Darkness",body="Maloriak blasts a 20 degree cone shaped area in front of him in Engulfing Darkness, inflicting $92787s1 Shadow damage and reducing the healing dealt by $92787s2% to players within the area for $92787d.",difficultyIDs={5,6}},
			{id=2946,title="Vile Swill",body="The Dark Magic causes five Vile Swill to appear. These horrible slimes continually cast Dark Sludge on random players until slain.",difficultyIDs={5,6}},
			{id=2947,title="Dark Sludge",body="The Vile Swill targets a random player with Dark Sludge. The sludge leaves a puddle on the ground for $92930d. that inflicts $92930s1 Shadow damage every 0.5 seconds to all players within a $92930A1 yard radius.",difficultyIDs={5,6}},
			{id=2948,title="Stage Two: Unpredictable Results",body="At 25% remaining health, Maloriak stops throwing vials into the cauldron. He deals more melee damage, gains a new set of abilities, and immediately frees all remaining experiments in the growth chambers."},
			{id=2949,title="Release All",body="Maloriak releases all remaining Aberrations and the two Prime Subjects from their growth chambers."},
			{id=2950,title="Magma Jets",body="Maloriak releases a stream of small fire fissures in front of him. These fissures deal $78095s1 Fire damage to all players within $78095A1 yards. The fissures also leave behind a persistent burning effect that inflicts $78124s1 Fire damage to all nearby players."},
			{id=2951,title="Absolute Zero",body="Maloriak summons a sphere of sub-freezing energy near a random player. If this sphere comes within $78206A1 yards of any player, it explodes, inflicts $78208s1 Frost damage, and knocks back any player within $78208A1 yards."},
			{id=2952,title="Acid Nova",body="Maloriak inflicts $78225s1 Nature damage per second to all players for $78225d."},
			{id=2953,title="Prime Subject",body="These experimental drakonids enhance allies' damage with Growth Catalyst."},
			{id=2954,title="Growth Catalyst",body="Each Prime Subject increases the damage of other Prime Subjects within $77987A1 yards by $77987s1% and reduces their damage taken by $77987s2%. This effect stacks, and also affects Maloriak and Aberrations."},
		},
	},
