		sections={
			{id=3276,title="Electrocute",body="Throughout the battle, Nefarian electrocutes the entire raid every time he loses 10% of his health. Electrocute generates a massive crackle of lightning that inflicts $81272s1 Nature damage on all players."},
			{id=3277,title="Stage One: Rise, Sister!",body="Nefarian reveals the undead form of his sister, Onyxia, and the two dragons attack the raid."},
			{id=3278,title="Children of Deathwing",body="Nefarian and Onyxia attack $78619s1% faster when they are within $78619A1 yards of each other."},
			{id=3279,title="Nefarian"},
			{id=3280,title="Hail of Bones",body="Before Nefarian lands at the beginning of Stage One, he summons some Animated Bone Warriors. Each summoning inflicts $78684s1 Shadow damage to nearby players within $78864a1 yards.$[!4,6\n\nIn 25 player raids Nefarian summons additional Animated Bone Warriors.$]"},
			{id=3281,title="Shadowflame Breath",body="Nefarian's dragon breath inflicts $77826s2 Shadowflame damage to players within a $77826a2 yard long 60 degree cone, and fully recharges the energy of any Animated Bone Warriors in the breath's area."},
			{id=3282,title="Tail Lash",body="Nefarian sweeps his tail at any enemies in a 60 degree cone facing behind him, inflicting $77827s1 Physical damage and stunning them for $77827d."},
			{id=3289,title="Animated Bone Warriors",body="Early in stage one and before he lands, Nefarian summons Animated Bone Warriors. The skeletons possess an energy bar that depletes over time. They collapse if they run out of energy, but restore energy if struck by Shadowflame Breath or Shadowblaze."},
			{id=3290,title="Empowering Strikes",body="The Animated Bone Warriors grow more powerful over time, increasing their damage dealt by $79330s1% and their movement speed by $79330s2%. This effect stacks."},
			{id=3295,title="Dominion",body="Nefarian periodically dominates the mind of random players, seizing control of their bodies for $79318d. Dominated players walk towards a portal that appears. If a Dominated player reach the portal, it kills them.\n\nDominion grants players access to three special abilities.",difficultyIDs={5,6}},
			{id=3296,title="Siphon Power",body="Dominated players absorb a little of the immense power Nefarian is using to control them to gain the Stolen Power effect.",difficultyIDs={5,6}},
			{id=3297,title="Stolen Power",body="Dominated players strike back against Nefarian with vengeance and anger, increasing their damage and healing by $80627s1% for $80627d. This effect stacks.",difficultyIDs={5,6}},
			{id=3298,title="Free Your Mind",body="Dominated players focus their will to break Nefarian's Dominion over them, which also increases their movement speed by $98932s1% for $98932d.",difficultyIDs={5,6}},
			{id=3283,title="Onyxia"},
			{id=3284,title="Electrical Energy",body="Onyxia gains energy over time and more energy when Nefarian casts Electrocute. If Onyxia reaches full energy, she explodes in an Electrical Overload, killing all players."},
			{id=3285,title="Lightning Discharge",body="Onyxia discharges electricity from the orbs along her sides, inflicting $77942s1 Nature damage to targets within $77942A2 yards."},
			{id=3286,title="Shadowflame Breath",body="Onyxia's dragon breath inflicts $77826s2 Shadowflame damage to players within a $77826a2 yard long 60 degree cone, and fully recharges the energy of any Animated Bone Warriors in the breath's area."},
			{id=3287,title="Tail Lash",body="Onyxia sweeps her tail at any enemies in a 60 degree cone facing behind her, inflicting $77827s1 Physical damage and stunning them for $77827d."},
			{id=3288,title="Electrical Overload",body="If Onyxia reaches full energy, she releases a massive Electrical Overload and causes $78999s1 Nature damage to all players."},
			{id=3291,title="Stage Two: Curse You, Mortals!",body="When the players kill Onyxia, Nefarian takes to the air and fills the room with magma except for three platforms. Nefarian then summons a Chromatic Prototype upon each of the platforms."},
			{id=3299,title="Chromatic Prototype",body="A Chromatic Prototype appears on each platform. They stand in place and cast Blast Nova."},
			{id=3300,title="Blast Nova",body="Chromatic Prototypes cast Blast Nova, which inflicts $80735s1 Fire damage every $80734t1 sec. to all enemies."},
			{id=3301,title="Shadowflame Barrage",body="While flying, Nefarian breathes a Shadowflame Barrage at random players, inflicting $78621s1 Shadowflame damage."},
			{id=3302,title="Explosive Cinders",body="While flying, Nefarian occasionally targets random players with Explosive Cinders, coating them in explosive residue that inflicts $79339s1 Fire damage every $79339t1 seconds.\n\nThe residue detonates after $79339d., inflicting $79347s1 Fire damage to players within $79347A1 yards.",difficultyIDs={5,6}},
			{id=3292,title="Stage Three: You Simply Will Not Die!",body="After the players kill all the Chromatic Prototypes, the lava subsides, and Nefarian lands to finish the battle."},
			{id=3303,title="Shadowflame Breath",body="Nefarian's dragon breath inflicts $77826s2 Shadowflame damage to players within a $77826a2 yard long 60 degree cone, and fully recharges the energy of any Animated Bone Warriors in the breath's area."},
			{id=3304,title="Tail Lash",body="Nefarian sweeps his tail at any enemies in a 60 degree cone facing behind him, inflicting $77827s1 Physical damage and stunning them for $77827d."},
			{id=3305,title="Shadowblaze Spark",body="Nefarian creates a shadowy blaze at a nearby location that spreads quickly, inflicting $81007s1 Shadowflame damage to all enemies within $81007A1 yards and reanimating any Animated Bone Warriors."},
			{id=3306,title="Animated Bone Warriors",body="Animated Bone Warriors can be reanimated in Stage Three. The skeletons possess an energy bar that depletes over time. They collapse if they run out of energy, but restore energy if struck by Shadowflame Breath or Shadowblaze."},
			{id=3307,title="Empowering Strikes",body="The Animated Bone Warriors grow more powerful over time, increasing their damage dealt by $79330s1% and their movement speed by $79330s2%. This effect stacks."},
		},
	},
	[175]={
		encounterID=175,
		instanceID=76,
		order=1,
		name="High Priest Venoxis",
		lore="Originally sent to kill Hakkar, Venoxis became enslaved to the murderous entity before falling to Azeroth's heroes. Through the efforts of the Soulflayer's agents, Venoxis has been ripped from the spirit world and ordered to defend Zul'Gurub with his venomous serpentine minions.",
		dungeonEncounterID=1178,
		uiMapID=337,
		pin={x=0.51,y=0.5374},
		difficultyIDs={1,2},
		npcIDs={52155},
		displayIDs={37788},
		loot={
			{itemID=69600,diffs={1,2,3,4,5,6},faction=-1},
			{itemID=69601,diffs={1,2,3,4,5,6},faction=-1},
			{itemID=69602,diffs={1,2,3,4,5,6},faction=-1},
			{itemID=69603,diffs={1,2,3,4,5,6},faction=-1},
			{itemID=69604,diffs={1,2,3,4,5,6},faction=-1},
		},
		sections={
			{id=2787,title="Stage One: A Venomous Labyrinth",difficultyIDs={2,4,5,6}},
			{id=2800,title="Venomous Effusion",body="During the encounter a maze of poison clouds appears on the ground. The poison inflicts $96685s1 Nature damage to enemies that step into the clouds.",difficultyIDs={2,4,5,6}},
			{id=2802,title="Word of Hethiss",body="At the start of the battle, High Priest Venoxis calls upon the Word of Hethis. This inflicts $96560s1 Nature damage to players within $96560A1 yards and knocks them back.",difficultyIDs={2,4,5,6}},
			{id=2795,title="Whispers of Hethiss",body="High Priest Venoxis focuses a beam of poison on a random player, inflicting $96469s1 Nature damage every $96466t2 seconds.",difficultyIDs={2,4,5,6}},
			{id=2796,title="Toxic Link",body="High Priest Venoxis links two players with a toxic beam, inflicting $96478s1 Nature damage every $96477t1 seconds to both players. The Toxic Link lasts for $96477d or until both targets move farther away than $96476a1 yards from each other. When Toxic Link breaks, it causes a Toxic Explosion at the location of each linked player.",difficultyIDs={2,4,5,6}},
			{id=2803,title="Toxic Explosion",body="When Toxic Link breaks, it causes a Toxic Explosion at the location of each linked player. Toxic Explosion inflicts $96489s1 Nature damage to players within $96489A1 yards.",difficultyIDs={2,4,5,6}},
			{id=2791,title="Stage Two: The Mortal Coil Unwinds",body="After a set period of time, High Priest Venoxis transforms into an avatar of Hethiss, the snake god.",difficultyIDs={2,4,5,6}},
			{id=3486,title="Venomous Effusion",body="During the encounter a maze of poison clouds appears on the ground. The poison inflicts $96685s1 Nature damage to enemies that step into the clouds.",difficultyIDs={2,4,5,6}},
			{id=2797,title="Blessing of the Snake God",body="High Priest Venoxis takes on the avatar of Hethiss, the snake god. In this form, Venoxis' physical damage dealt increases by $96512s1% but he no longer dodges or parries attacks.",difficultyIDs={2,4,5,6}},
			{id=2798,title="Pool of Acrid Tears",body="High Priest Venoxis summons a venomous puddle near the player farthest from him. The puddle grows over time and inflicts $96521s1 Nature damage every $96520t1 seconds to players that stand in it.",difficultyIDs={2,4,5,6}},
			{id=2799,title="Breath of Hethiss",body="High Priest Venoxis spews forth a stream of acrid venom that inflicts $96744s1 Nature damage to enemies in a $96744a1-yard cone in front of him every $96509t1 seconds for $96509d.",difficultyIDs={2,4,5,6}},
			{id=2792,title="Stage Three: Bloodvenom!",body="High Priest Venoxis moves to his altar, absorbs all of the Pools of Acrid Tears in the room, and then casts Bloodvenom. After Bloodvenom ends, Venoxis enters a state of Venom Withdrawal and then returns to stage one.",difficultyIDs={2,4,5,6}},
			{id=2793,title="Bloodvenom",body="Venoxis creates up to three tendrils of poison that follow players around the room for $96637d.  Bloodvenom tendrils inflict $96638s1 Nature damage to players within $96638A1 yards every $97099t1 seconds.",difficultyIDs={2,4,5,6}},
			{id=2794,title="Venom Withdrawal",body="After Bloodvenom completes, High Priest Venoxis suffers from Venom Withdrawal for $96653d. Venom Withdrawal stuns Venoxis causes him to take $96653s1% additional damage. Once Venom Withdrawal expires, Venoxis begins his stage one activities again.",difficultyIDs={2,4,5,6}},
			{id=2801,title="Poison Cloud",body="The stairs and altar surrounding High Priest Venoxis are covered in a powerful poison gas that inflicts $96730s1 Nature damage every $96729t1 seconds.",difficultyIDs={2,4,5,6}},
			{id=3334,title="Heroic Difficulty Only",body="Zul'Gurub is only available in Heroic Difficulty.",difficultyIDs={1,3}},
		},
	},
	[176]={
		encounterID=176,
		instanceID=76,
		order=2,
		name="Bloodlord Mandokir",
		lore="The infamous Bloodlord Mandokir died a torturous death before Bloodscalp trolls desecrated his body years ago. Word has now spread that Mandokir walks the jungles of Stranglethorn yet again, using the corpse of the mighty Bloodscalp chieftain Gan'zulah as a host for his malevolent spirit.",
		dungeonEncounterID=1179,
		uiMapID=337,
		pin={x=0.6048,y=0.7994},
		difficultyIDs={1,2},
		npcIDs={52151},
		displayIDs={37816},
		loot={
			{itemID=69608,diffs={1,2,3,4,5,6},faction=-1},
			{itemID=69609,diffs={1,2,3,4,5,6},faction=-1},
			{itemID=69605,diffs={1,2,3,4,5,6},faction=-1},
			{itemID=69606,diffs={1,2,3,4,5,6},faction=-1},
