			{itemID=68823,diffs={},faction=-1},
		},
		sections={
			{id=2610,title="Decapitate",body="Bloodlord Mandokir charges a random player and inflicts $96684s1 Physical damage.",difficultyIDs={2,4,5,6}},
			{id=2611,title="Level Up",body="When Bloodlord Mandokir kills a player, he Levels Up, increasing his Physical damage dealt by $96662s1%. This effect stacks.",difficultyIDs={2,4,5,6}},
			{id=2612,title="Devastating Slam",body="Bloodlord Mandokir chooses a random player, then turns and leaps into the air and comes crashing down on them, inflicting $96743s1 Physical damage in a forward facing 45 degree cone.",difficultyIDs={2,4,5,6}},
			{id=2613,title="Bloodletting",body="Bloodlord Mandokir applies Bloodletting on a random player, inflicting $96776s1% of the players current health as Shadow damage every $96776t1 seconds for $96776d.",difficultyIDs={2,4,5,6}},
			{id=2614,title="Frenzy",body="At 20% remaining health, Bloodlord Mandokir goes into a Frenzy and increases his attack speed by $96800s1%.  While Frenzied, Bloodlord Mandokir will only cast Decapitate, but performs the ability at a higher rate than before.",difficultyIDs={2,4,5,6}},
			{id=2615,title="Ohgan",body="Ohgan is Bloodlord Mandokir's trusty Raptor. The undead Ohgan sees and kills the Chained Spirits when Mandokir orders him to do so.",difficultyIDs={2,4,5,6}},
			{id=2616,title="Ohgan's Orders",body="Bloodlord Mandokir dismounts from Ohgan and instructs him to kill the Chained Spirits in the area.  If Ohgan reaches a Chained Spirit, he kills it and acquires a new Chained Spirit as his target.",difficultyIDs={2,4,5,6}},
			{id=2617,title="Reanimate Ohgan",body="Bloodlord Mandokir resurrects Ohgan after the players kill the raptor. Ohgan resumes his Orders from when he was alive.",difficultyIDs={2,4,5,6}},
			{id=2618,title="Chained Spirit",body="Eight Chained Spirits stand ready to aid the players against Bloodlord Mandokir. Chained Spirits perform Revive on dead players during the fight.",difficultyIDs={2,4,5,6}},
			{id=2619,title="Revive",body="Chained Spirits periodically bring dead players back to life and then empower them with Spirit's Vengeance.",difficultyIDs={2,4,5,6}},
			{id=2620,title="Spirit's Vengeance",body="The Chained Spirit empowers the newly Revived player, increasing damage and healing done by $96493s2%, maximum health by $96494s1%, and decreasing all damage taken by $96494s2% for the duration of the fight. This effect stacks.",difficultyIDs={2,4,5,6}},
			{id=3338,title="Heroic Difficulty Only",body="Zul'Gurub is only available in Heroic Difficulty.",difficultyIDs={1,3}},
		},
	},
	[177]={
