			{id=2875,title="Stage One: No One Pushes Us Around!",body="Daakara begins the encounter in troll form. He performs Grievous Throw at random players and uses Whirlwind against nearby enemies.",difficultyIDs={2,4,5,6}},
			{id=2876,title="Grievous Throw",body="Daakara throws his weapon at a random player, causing them to bleed profusely for $43093d. or until fully healed.  The wound inflicts $43093s1 damage every $43093t1 seconds.",difficultyIDs={2,4,5,6}},
			{id=2877,title="Whirlwind",body="Daakara attacks nearby enemies in a whirlwind of steel. After channeling for 2 seconds he inflicts 110% of a normal melee attack to enemies within 8 yards.",difficultyIDs={2,4,5,6}},
			{id=2878,title="Stage Two: Got Me Some New Tricks!",body="Daakara absorbs the essence of either the bear or lynx.",difficultyIDs={2,4,5,6}},
			{id=2879,title="Essence of the Bear",difficultyIDs={2,4,5,6}},
			{id=2880,title="Surge",body="Daakara charges the most distant enemy, inflicting $42402s2 Physical damage. In addition, Physical damage dealt to the target increases by $42402s3% for $42402d.",difficultyIDs={2,4,5,6}},
			{id=2881,title="Nearly Overpowered Blow",body="Daakara instantly attacks his target, inflicting $43456s1% of a normal melee attack. This attack cannot be blocked, dodged, or parried.",difficultyIDs={2,4,5,6}},
			{id=2882,title="Creeping Paralysis",body="Daakara inflicts a slow paralysis on all players, stunning them for $43437d. if not removed within $43095t1 sec.",difficultyIDs={2,4,5,6}},
			{id=2883,title="Essence of the Lynx",difficultyIDs={2,4,5,6}},
			{id=2884,title="Amani Lynx",body="Immediately after transforming into a Lynx, Daakara summons two Amani Lynx to attack players. These Lynx see through any stealth or invisibility effects.",difficultyIDs={2,4,5,6}},
			{id=3522,title="Feral Swipe",body="The Amani Lynx swipes at its current target, inflicting $43357s2 Physical damage and reducing the target's movement speed by $43357s1% for $43357d.",difficultyIDs={2,4,5,6}},
			{id=2885,title="Lynx Rush",body="Daakara randomly charges players. Each charge inflicts $43153s2 Physical damage and causes the target to bleed for $43153o3 additional damage over $43153d.",difficultyIDs={2,4,5,6}},
			{id=2886,title="Claw Rage",body="Daakara charges a random target, immobilizing them and unleashing a flurry of rapid attacks. Each attack further weakens the target, increasing their Physical damage taken by $43150s2. This effect stacks up to 10 times.",difficultyIDs={2,4,5,6}},
			{id=2887,title="Stage Three: Lot More Gonna Fall!",body="Daakara absorbs the essence of either the eagle or dragonhawk.",difficultyIDs={2,4,5,6}},
			{id=2888,title="Essence of the Eagle",difficultyIDs={2,4,5,6}},
			{id=2889,title="Lightning Totem",body="Daakara periodically summons a Lightning Totem to attack his enemies. This totem has low health.",difficultyIDs={2,4,5,6}},
			{id=2890,title="Lightning",body="The Lightning Totem casts Lightning at a random player, inflicting $43301s1 Nature damage and bouncing to a maximum of $43301x1 additional nearby enemies, inflicting $43301f1 times as much damage with each bounce.",difficultyIDs={2,4,5,6}},
			{id=2891,title="Feather Cyclone",body="Immediately after transforming into an Eagle, Daakara conjures one Feather Cyclone for each living player. These cyclones persist for the remainder of the encounter, but only move when affected by Sweeping Winds.",difficultyIDs={2,4,5,6}},
			{id=2892,title="Zap",body="Feather Cyclones unleash a blast of electricity when a spell is cast nearby, inflicting $43137s1 Nature damage to the caster of the spell.",difficultyIDs={2,4,5,6}},
			{id=2893,title="Storm",body="Feather Cyclones inflict $43121s1 Nature damage on enemies within $43121A1 yds.",difficultyIDs={2,4,5,6}},
			{id=2894,title="Sweeping Winds",body="Daakara casts this spell repeatedly throughout this stage. After casting Sweeping Winds, each feather cyclone moves rapidly toward a player.",difficultyIDs={2,4,5,6}},
			{id=2895,title="Essence of the Dragonhawk",difficultyIDs={2,4,5,6}},
			{id=2896,title="Flame Breath",body="Daakara inflicts $43140s3 Fire damage to enemies in a 60 degree cone in front of him. The Flame Breath also leaves a line of fire that inflicts $97497s1 Fire damage every $97497t1 sec. to enemies within $97497A1 yards of the path of flame.",difficultyIDs={2,4,5,6}},
			{id=2897,title="Flame Whirl",body="Daakara whirls around and spits flame at all players, inflicting $43208s1 Fire damage and increasing Fire damage dealt to them by $44090s1% for $44090d. This stacks up to 10 times.",difficultyIDs={2,4,5,6}},
			{id=2898,title="Pillar of Fire",body="Daakara summons a pillar of fire at a random player's location. The pillar inflicts $43217s1 Fire damage to enemies within $43217R1 yds. every $43218t1 sec. and persists for $43218d.",difficultyIDs={2,4,5,6}},
			{id=3351,title="Heroic Difficulty Only",body="Zul'Aman is only available in Heroic Difficulty.",difficultyIDs={1,3}},
		},
	},
