			{id=3668,title="Stardust",body="Tyrande scatters a diffuse trail of star energy into the wind, inflicting $102173s1 Arcane damage to all players.",difficultyIDs={2,4,5,6}},
			{id=3669,title="Moonlance",body="Tyrande summons forth a powerful lance of moon energy that travels along the ground and splits into three parts after several seconds.  Each Moonlance inflicts $102149s1 Arcane damage to all players within $102149A1 yards and stuns them for $102149d.",difficultyIDs={2,4,5,6}},
			{id=3670,title="Eyes of the Goddess",body="Tyrande summons forth the twin eyes of Elune, the Moon Goddess.  Players cannot attack the Eyes of the Goddess.",difficultyIDs={2,4,5,6}},
			{id=3671,title="Piercing Gaze of Elune",body="The Eyes of Elune travel in a circular motion around Tyrande, emitting the Piercing Gaze of Elune every $102182t1 sec.  Piercing Gaze of Elune inflicts $102183s1 Arcane damage to all players within $102183A1 yards and silences them for $102183d.",difficultyIDs={2,4,5,6}},
			{id=3672,title="Lunar Guidance",body="At 80% remaining health, Tyrande beseeches Elune for guidance.  Tyrande is imbued with Lunar Guidance, allowing her spells to cast $102472s1% faster.  Tyrande gains a second stack of Lunar Guidance when she reaches 55% remaining health.",difficultyIDs={2,4,5,6}},
			{id=3673,title="Tears of Elune",body="At 30% remaining health, Tyrande cries out for aid from the Moon Goddess.  Tears of Elune rain from the sky for the remainder of the battle, inflicting $102244s1 Arcane damage to players within $102244a1 yards.",difficultyIDs={2,4,5,6}},
			{id=3674,title="Heroic Difficulty Only",body="End Time is only available on Heroic Difficulty.",difficultyIDs={1,3}},
