		sections={
			{id=3675,title="Temporal Blast",body="Murozond inflicts $102381s1 Arcane damage to all nearby enemies and increases their Arcane damage taken by $102381s2% for $102381d.",difficultyIDs={2,4,5,6}},
			{id=3676,title="Distortion Bomb",body="Murozond launches an orb of temporal energy at the location of a random player. When the orb reaches this location, it explodes and leaves an $101984A1 yard radius area of temporal distortion. The distortion area inflicts $101984s1 Arcane damage every second to all enemies standing within the area.",difficultyIDs={2,4,5,6}},
			{id=3677,title="Infinite Breath",body="Inflicts $102569s1 Shadow damage to all enemies in front of the caster.",difficultyIDs={2,4,5,6}},
			{id=3678,title="Nozdormu",body="Nozdormu is unable to assist the players directly, but grants them the Blessing of the Bronze Dragonflight.",difficultyIDs={2,4,5,6}},
			{id=3679,title="Blessing of the Bronze Dragonflight",body="Blesses the target with the power of the Bronze Dragonflight. Melee, ranged, and spell casting speed is increased by $102364s1%. Movement speed increased by $102364s2%.",difficultyIDs={2,4,5,6}},
			{id=3680,title="Hourglass of Time",body="Murozond stole the Hourglass of Time and trapped it here within the End Time of Azeroth. The Hourglass casts Rewind Time when a player interacts with it, but the Hourglass can only be used up to five times during the encounter.",difficultyIDs={2,4,5,6}},
			{id=3681,title="Rewind Time",body="The Reverse Time effect rewinds everything back to the beginning of the encounter. The reversal restores each player's health and mana, then resets all of their ability cooldowns. The reversal also removes all Distortion Bombs.",difficultyIDs={2,4,5,6}},
			{id=4163,title="Heroic Difficulty Only",body="End Time is only available in Heroic Difficulty.",difficultyIDs={1,3}},
		},
	},
	[290]={
		encounterID=290,
		instanceID=185,
		order=1,
		name="Peroth'arn",
		lore="Like many of his fellow Highborne, Peroth'arn swore allegiance to the corrupted Xavius in exchange for gifts of demonic power. \n\nAs a master of fiendish magic and recipient of the satyr curse, Peroth'arn stands outside Azshara's palace in defense of the Burning Legion, ready to destroy those hoping to disrupt the entrance of the Dark Titan, Sargeras, into Azeroth.",
