			{id=4164,title="Heroic Difficulty Only",body="Well of Eternity is only available in Heroic Difficulty.",difficultyIDs={1,3}},
			{id=4227,title="Corrupting Touch",body="Peroth'arn's melee strikes apply Corrupting Touch on his current target, increasing damage taken by $108101s1% for $108101d. This effect stacks.",difficultyIDs={2,4,5,6}},
			{id=4228,title="Fel Flames",body="Peroth'arn calls down a fel fireball on a random player, inflicting $109824s1 Fire damage and leaving behind fire that causes $108217s1 Fire damage every second for $108193d.",difficultyIDs={2,4,5,6}},
			{id=4229,title="Fel Decay",body="Peroth'arn's sickly touch causes a random target to decay from within, instantly inflicting $105544s1 Shadow damage and $105544s2 Shadow damage every second for $105544d. Any healing done to the afflicted player causes the healer to suffer $108124s1% of the amount healed as Shadow damage.",difficultyIDs={2,4,5,6}},
			{id=4091,title="Drain Essence",body="At 60% remaining health, Peroth'arn stuns all enemies and inflicts Shadow damage every second for $104905d.",difficultyIDs={2,4,5,6}},
			{id=4092,title="The Eyes of Peroth'arn",body="After Illidan interrupts Drain Essence, Peroth'arn returns to the shadows to ambush the heroes. Peroth'arn unleashes his Eyes of Peroth'arn to search for the players. Players gain the protection of their Shadowcloaks to help them avoid the detection range of the Eyes.\n\nIf players avoid detection for 40 seconds, Peroth'arn becomes visible and weakened with the Enfeebled effect.\n\nIf an Eye of Peroth'arn discovers a player, Peroth'arn marks the player with Easy Prey, leaps out of the shadows, and attacks the discovered player.",difficultyIDs={2,4,5,6}},
			{id=4225,title="Easy Prey",body="When an Eye of Peroth'arn discovers a player, Peroth'arn casts Fel Quickening and marks his new target as Easy Prey. The mark removes the player's Shadowcloak or stealth and stuns them for $105493d.",difficultyIDs={2,4,5,6}},
			{id=4226,title="Fel Quickening",body="Peroth'arn increases his attack speed by $105526s1% for $105526d.",difficultyIDs={2,4,5,6}},
			{id=4222,title="Enfeebled",body="If after 40 seconds Peroth'arn has not detected a player with his Eyes, Peroth'arn can no longer remain hidden in the shadows and becomes Enfeebled. This effect stuns Peroth'arn and increases his damage taken by $105442s1% damage for $105442d.",difficultyIDs={2,4,5,6}},
			{id=4100,title="Endless Frenzy",body="At 20% remaining health, Peroth'arn frenzies and increases his damage by $105521s1%.",difficultyIDs={2,4,5,6}},
		},
	},
	[291]={
		encounterID=291,
		instanceID=185,
		order=2,
		name="Queen Azshara",
		lore="The songs of Queen Azshara's beauty, majesty, and power are too numerous to count, but it was her vanity that drove the Highborne to summon the Burning Legion. She now watches her most trusted magi empower the portal where Sargeras will be brought into Azeroth, content to let multitudes of her servants die in advance of the Dark Titan's arrival.",
		dungeonEncounterID=1273,
		uiMapID=398,
		pin={x=0.4634,y=0.3696},
		difficultyIDs={2},
		npcIDs={88740,131071,143629,155126},
		displayIDs={39391},
		loot={
			{itemID=72833,diffs={},faction=-1},
			{itemID=72834,diffs={},faction=-1},
			{itemID=72835,diffs={},faction=-1},
			{itemID=72836,diffs={},faction=-1},
			{itemID=72837,diffs={},faction=-1},
			{itemID=72838,diffs={},faction=-1},
		},
		sections={
			{id=3968,title="Servant of the Queen",body="Queen Azshara charms a random player, causing them to become a puppet. Destroying the puppet strings releases the player from Azshara's control.",difficultyIDs={2,4,5,6}},
			{id=3969,title="Total Obedience",body="Queen Azshara attempts to charm every player and turn them into puppets for $103241d.",difficultyIDs={2,4,5,6}},
			{id=3956,title="Enchanted Magi",body="Queen Aszhara commands two of her Enchanted Magi to attack the players. When the players defeat an Enchanted Magus or enough time elapses, another two Magi enter combat. Each Enchanted Magi possess one of three schools of magic.\n\nWhen the players defeat all of the Enchanted Magi, Queen Azshara retreats from combat and the players complete the encounter.",difficultyIDs={2,4,5,6}},
			{id=3957,title="Frost Magus",difficultyIDs={2,4,5,6}},
			{id=3958,title="Ice Fling",body="The Enchanted Magus inflicts $102478s1 Frost damage on a random player.",difficultyIDs={2,4,5,6}},
			{id=3959,title="Coldflame",body="The Enchanted Magus's Coldflame inflicts $102466s1 Frost damage in a line, and continues to inflict $102466s2 Frost damage every $102466t2 sec. for $102466d.",difficultyIDs={2,4,5,6}},
			{id=3960,title="Blades of Ice",body="The Enchanted Magus charges at the location of a random player, then inflicts $102468s1% weapon damage as Frost damage to all players within $102468A1 yards of the location.",difficultyIDs={2,4,5,6}},
			{id=3961,title="Fire Magus",difficultyIDs={2,4,5,6}},
			{id=3962,title="Fireball",body="The Enchanted Magus inflicts $102265s1 Fire damage on its current target.",difficultyIDs={2,4,5,6}},
			{id=3963,title="Firebomb",body="The Enchanted Magus hurls a fiery bomb at a random player, inflicting $102482s1 Fire damage on them and other players within $102482A1 yards and reducing their movement speed for $102482d.",difficultyIDs={2,4,5,6}},
			{id=3964,title="Blast Wave",body="The Enchanted Magus unleashes a wave of flame, inflicting $102483s1 Fire damage on enemies within $102483A1 yards.",difficultyIDs={2,4,5,6}},
			{id=3965,title="Arcane Magus",difficultyIDs={2,4,5,6}},
			{id=3966,title="Arcane Shock",body="The Enchanted Magus inflicts $102464s1 Arcane damage every $102463t1 sec. on all enemies within $102464A1 yards.",difficultyIDs={2,4,5,6}},
			{id=3967,title="Arcane Bomb",body="The Enchanted Magus summons an arcane bomb that inflicts $102455s2 Arcane damage and reduces the movement speed of players within $102455A1 yards of its impact by $102455s1%.",difficultyIDs={2,4,5,6}},
			{id=4165,title="Heroic Difficulty Only",body="Well of Eternity is only available in Heroic Difficulty.",difficultyIDs={1,3}},
		},
	},
	[292]={
		encounterID=292,
		instanceID=185,
		order=3,
		name="Mannoroth and Varo'then",
		lore="Varo'then, head of Queen Azshara's personal guard, and Mannoroth, the pit lord whose blood will corrupt the entire orc race, stand as the last line of defense against those hoping to bar Sargeras's entry into Azeroth. Though both Tyrande and Illidan have fought bravely thus far, the fate of Azeroth will be decided at the Well of Eternity's very brink.",
		dungeonEncounterID=1274,
		uiMapID=398,
		pin={x=0.873,y=0.4826},
		difficultyIDs={2},
		npcIDs={54969},
		displayIDs={38996,39127},
		loot={
			{itemID=72848,diffs={},faction=-1},
			{itemID=72898,diffs={},faction=-1},
			{itemID=72899,diffs={},faction=-1},
			{itemID=72839,diffs={},faction=-1},
			{itemID=72840,diffs={},faction=-1},
			{itemID=72841,diffs={},faction=-1},
			{itemID=72842,diffs={},faction=-1},
			{itemID=72843,diffs={},faction=-1},
			{itemID=72844,diffs={},faction=-1},
			{itemID=72845,diffs={},faction=-1},
			{itemID=72846,diffs={},faction=-1},
			{itemID=72847,diffs={},faction=-1},
		},
		sections={
			{id=3684,title="Heroic Difficulty Only",body="Well of Eternity is only available on Heroic Difficulty.",difficultyIDs={1,3}},
			{id=4298,title="Stage One: Dealing with the Rabble",body="Players must defeat Captain Varo'then while Illidan and Tyrande fight off Mannoroth and the demonic forces entering from the Well of Eternity.",difficultyIDs={2,4}},
			{id=4270,title="Mannoroth",body="Mannoroth faces off in mortal combat against Illidan Stormrage.",difficultyIDs={2,4}},
			{id=4285,title="Fel Firestorm",body="Mannoroth unleashes a Fel Firestorm, rapidly creating $103891A1 yard radius Fel Flames around the area for $103888d. Fel Flames inflict $103891s1 Fire damage every second to any player standing within them.",difficultyIDs={2,4}},
			{id=4286,title="Felblade",body="Mannoroth coats his mighty polearm in demonic fire, gaining a chance to deal $103972s1 additional Fire damage when striking opponents in melee.",difficultyIDs={2,4}},
			{id=4275,title="Fel Drain",body="If the players inflict a significant amount of damage to Mannoroth while Captain Varo'then lives, Mannoroth sacrifices Captain Varo'then and heals himself to full health.",difficultyIDs={2,4}},
			{id=4299,title="Doomguard Devastator",body="These massive demons from the Well of Eternity seek to protect Mannoroth, but Tyrande stands in their way.",difficultyIDs={2,4}},
			{id=4276,title="Dreadlord Debilitator",body="These Dread Lords periodically enter from the Well of Eternity, then attempt to debilitate Tyrande.",difficultyIDs={2,4}},
			{id=4277,title="Debilitating Flay",body="The Debilitating Dreadlord disables Tyrande, preventing her from performing any actions and allowing Doomguards to swarm the area.",difficultyIDs={2,4}},
			{id=4271,title="Captain Varo'then",body="Captain Varo'then attacks the players to prevent them from interfering with Mannoroth's concentration.",difficultyIDs={2,4}},
			{id=4289,title="Magistrike",body="Varo'then charges his sword with Arcane and Fire magics, dealing $103669s1 Fire damage to an enemy and arcing to another nearby foe. Affects up to $103669x1 total targets.",difficultyIDs={2,4}},
			{id=4272,title="Illidan Stormrage",body="Illidan occupies Mannoroth in melee combat so the players are free to defeat Captain Varo'then.",difficultyIDs={2,4}},
			{id=4278,title="Darklance",body="Illidan conjures forth a spear of dark magical energy, piercing Mannoroth for $104394s1 Shadow damage.",difficultyIDs={2,4}},
			{id=4279,title="Aura of Immolation",body="Illidan shrouds himself in magical flames, inflicting $104387s1 Fire damage to nearby enemies every $104379t1 seconds.",difficultyIDs={2,4}},
			{id=4280,title="Demon Rush",body="Illidan charges at Mannoroth, coursing with Fel energies and inflicting $104205s2% weapon damage to him.",difficultyIDs={2,4}},
			{id=4281,title="Demonic Sight",body="The Gift of Sargeras gives Illidan sight beyond sight, allowing him to dodge $104746s1% of Mannoroth's attacks.",difficultyIDs={2,4}},
			{id=4291,title="Taunt",body="Illidan goads Mannoroth into focusing attacks on him.",difficultyIDs={2,4}},
			{id=4290,title="Waters of Eternity",body="After Mannoroth creates a Fel Firestorm, Illidan splashes himself with the waters of the Well of Eternity. The water provides substantial magical powers and reduces the Fire damage taken by all nearby allies by $103952s2%."},
			{id=4273,title="Tyrande Whisperwind",body="Tyrande positions herself to intercept the rush of Doomguard Devastators exiting from the Well of Eternity with Lunar Shot.",difficultyIDs={2,4}},
			{id=4307,title="Lunar Shot",body="Tyrande holds off the demons exiting from the Well of Eternity with her Lunar Shot.",difficultyIDs={2,4}},
			{id=4283,title="Blessing of Elune",body="When a Dreadlord Debilitator casts Debilitating Flay upon her, Tyrande beseeches Elune for her blessing. This blessing affects all nearby allies, enchanting their attacks and spells to inflict additional Arcane damage to lesser demons.",difficultyIDs={2,4}},
			{id=4300,title="Stage Two: Flames and Darkness",body="After the players defeat Captain Varo'then, his enchanted Magistrike Blade lies on the ground. After a player throws  and embeds the blade into Mannoroth, the demon begins to take massive damage from the stored magic within the blade.",difficultyIDs={2,4}},
			{id=4301,title="Mannoroth",body="The wounded Mannoroth continues to fight, opening a Nether Portal to bring demonic allies into the fray.",difficultyIDs={2,4}},
			{id=4288,title="Embedded Blade",body="Players may pick up Captain Varo'then's magical elven blade and throw it towards Mannoroth. The blade embeds itself into Mannoroth's demonic armor. The magical blade then causes strikes against Mannoroth to have a chance to create a Magistrike Arc inflicting $105523s1 Fire damage to Mannoroth.",difficultyIDs={2,4}},
			{id=4284,title="Fel Fire Nova",body="After a player embeds the Magistrike blade within Mannoroth, the open wound emits a steady pulse of fel fire. Each pulse inflicts $105093s1 Fire damage to enemies."},
			{id=4287,title="Nether Portal",body="Mannoroth summons a portal to the Twisting Nether, allowing him to call forth demonic allies. As his remaining health dwindles, additional types of demons exit through the portal.",difficultyIDs={2,4}},
			{id=4294,title="Felhound",body="At 85% remaining health, Mannoroth summons a weak felhound to aid him in combat from the Nether Portal.",difficultyIDs={2,4}},
			{id=4295,title="Felguard",body="At 70% remaining health, Mannoroth also summons a Felguard from the Nether Portal to aid him in combat.",difficultyIDs={2,4}},
			{id=4296,title="Doomguard Devastator",body="At 60% remaining health, additional Doomguard Devastators begin to pour from the Nether Portal.",difficultyIDs={2,4}},
			{id=4297,title="Infernal",body="At 50% remaining health, Mannoroth calls down a hail of Infernals to aid him in combat.",difficultyIDs={2,4}},
			{id=4308,title="Illidan Stormrage",body="Illidan continues to fight Mannoroth with his host of Demon Hunter abilities.",difficultyIDs={2,4}},
			{id=4309,title="Tyrande Whisperwind",body="Tyrande runs out of arrows and beseeches Elune for help against the overwhelming number of demons.",difficultyIDs={2,4}},
			{id=4292,title="Hand of Elune",body="Tyrande is granted the full powers of the High Priestess of Elune, inflicting $105073s1 Arcane damage to three neaby lesser demons every $105072t1 seconds.",difficultyIDs={2,4}},
			{id=4303,title="Stage Three: Your World will be Unmade!",body="After Tyrande collapses upon destroying the rain of Infernals, Illidan then infuses himself to finish off Mannoroth.",difficultyIDs={2,4}},
			{id=4304,title="Mannoroth",body="Even heavily wounded Mannoroth continues to fight for his lord Sargeras.",difficultyIDs={2,4}},
			{id=4310,title="Embedded Blade",body="The embedded magical blade causes strikes against Mannoroth to have a chance to create a Magistrike Arc, inflicting $105523s1 Fire damage to Mannoroth.",difficultyIDs={2,4}},
			{id=4311,title="Fel Fire Nova",body="After a player embeds the Magistrike blade within Mannoroth, the open wound emits a steady pulse of fel fire. Each pulse inflicts $105093s1 Fire damage to enemies."},
			{id=4305,title="Illidan Stormrage",body="Illidan infuses himself with demonic energy to finish the fight.",difficultyIDs={2,4}},
			{id=4282,title="Gift of Sargeras",body="Illidan infuses himself and all nearby allies with the fel energies of the demon lord Sargeras, healing for $104998s3% of maximum health every $104998t3 seconds and dealing $105006s1 Fire damage to nearby enemies every $104998t2 seconds.",difficultyIDs={2,4}},
			{id=4306,title="Tyrande Whisperwind",body="Tyrande unleashes a massive blast of Arcane energy to destroy any nearby lesser demons, then collapses.",difficultyIDs={2,4}},
			{id=4312,title="Elune's Wrath",body="Tyrande unleases a blast of Arcane energy to destroy any nearby lesser demons.",difficultyIDs={2,4}},
			{id=4274,title="Malfurion Stormrage",body="Utilizing the powers of nature bestowed upon him by the demigod Cenarius, Malfurion Stormrage focuses the will of the living creatures of Azeroth upon the demonic portal hovering over the Well of Eternity. When Mannoroth reaches 25% remaining health, Malfurion casts a spell to cause the portal to violently implode and pull the demonic legions out of Azeroth.",difficultyIDs={2,4}},
		},
	},
