		sections={
			{id=3879,title="Stomp",body="Morchok performs a massive stomp, splitting $%103414s1 damage between all players within $103414A yards. Morchok's current target and their closest ally will take a double portion of the damage. $[!5,6\n\nIn Heroic Difficulty Stomp also increases the Physical damage taken by affected players by $103414s3% for $103414d.$]"},
			{id=3890,title="Crush Armor",body="Morchok strikes his current target, inflicting $103687s1% normal melee damage and reducing the target's armor by $103687s2% for $103687d. This effect stacks up to 10 times.",difficultyIDs={1,2,3,4}},
			{id=3876,title="Resonating Crystal",body="Morchok conjures an explosive crystal onto the battlefield that explodes after 12 sec. for massive Shadow damage. The explosion splits the damage between three random players, and the total damage inflicted increases depending on the distance of each player from the crystal.$[!4,6,7 \n\nIn 25 Player raids, the damage splits between seven random enemies.$]"},
			{id=3891,title="Furious",body="At 20% remaining health, Morchok becomes furious and increases his attack speed by $103846s1% and his damage inflicted by $103846s2%."},
			{id=3875,title="The Earth Consumes You!",body="Morchok uses the power of the earth to draw all players to him, inflicting $103821s3% of their total health as Physical damage every sec. for $103821d. While the power of the earth draws the players to him, Morchok also summons Earth's Vengeance."},
			{id=3877,title="Earth's Vengeance",body="Shards of Earth's Vengeance erupt from the ground, inflicting $%103178s1 Physical damage to nearby players within $103178A1 yards  and leaving behind obstacles."},
			{id=3878,title="Black Blood of the Earth",body="Morchok causes the Black Blood of the Earth to erupt outwards from him, inflicting $%103785s1 Nature damage and increasing Nature damage taken by $103785s2% every sec. while a player stands within the blood. This effect stacks up to 20 times."},
			{id=4262,title="Kohcrom",body="Upon reaching 90% remaining health, Morchok tears himself in half and creates his twin Kohcrom. He casts the same spells as Morchok, but a few seconds later.",difficultyIDs={5,6}},
