	[317]={
		encounterID=317,
		instanceID=187,
		order=4,
		name="Hagara the Stormbinder",
		lore="Hagara, one of the first students of arcane magic under the Forsaken, showed surprising potential for one who had started learning so late in life. But in her undisciplined attempts to bind elementals into servitude, she was ensnared and twisted by the Windlord, Al'Akir. Now fiercely loyal to the Twilight's Hammer, Hagara binds others for her elemental masters to torment.",
		dungeonEncounterID=1296,
		uiMapID=412,
		pin={x=0.5275,y=0.5205},
