		sections={
			{id=3912,title="Ice Lance",body="Hagara conjures crystals of ice that launch Ice Lance missiles towards a random player standing near Hagara. Ice Lances inflict $%105316s2 Frost damage in a $105316A2 yard area around the first player the missile impacts. $[!3,4,7 \n\nIn Normal and LFR difficulty, Ice Lance reduces the attack speed of all targets struck by $105316m3%.$]$[!5,6 \n\nIn Heroic difficulty, Ice Lance increases frost damage taken by $105316m3% per hit.$]"},
			{id=3913,title="Ice Tomb",body="Hagara traps two random players in a tomb of ice, stunning the targets until other players destroy the Ice Tombs. Players trapped within the tomb lose 5% of their maximum health every second.$[!2,4\n\nIn 25 player Normal difficulty Hagara traps five random players.$]$[!6\n\nIn 25 player Heroic difficulty Hagara traps six random players.$]",difficultyIDs={1,2,3,4,5,6}},
			{id=4158,title="Shattered Ice",body="Hagara launches a blast of ice at a random player, inflicting $%105289s1 Frost damage and reducing the player's movement speed for $105289d."},
			{id=4159,title="Focused Assault",body="Hagara rapidly slices at her current target, swinging for $107850s1% normal weapon damage every $107851t2 sec.  for $107851d."},
			{id=3914,title="Frozen Tempest",body="Hagara channels and fills the platform with a tempest of water and ice. The Tempest protects Hagara from all attacks and spells."},
			{id=4069,title="Binding Crystal",body="Destroying all four of the binding crystals stops Hagara's channeling of Frozen Tempest."},
			{id=3915,title="Watery Entrenchment",body="Any player standing within Hagara's water bubble drowns, inflicting damage equal to $110317s2% of their maximum health every second and reducing their movement speed by $110317s3%."},
			{id=4323,title="Ice Wave",body="Four equidistant lines of ice extend out from Hagara and sweep across the platform. The Ice Wave inflicts $%105314s1 Frost damage on any player caught by its movement and increases their Frost damage taken by $105314s2% for $105314d."},
			{id=4324,title="Icicle",body="Snowpacked Icicles fall around the edge of the platform. Where the Icicle impacts the ground, it inflicts 100000 Frost damage and knocks back any nearby players within $69425A1 yards.",difficultyIDs={1,2,3,4,5,6}},
			{id=4325,title="Frostflake",body="Hagara places a Frostflake on a random player, reducing their movement speed by $109325s1% and an additional $109325s1% every $109325t2 sec for $109325d. When the Frostflake effect expires, it deals damage equal to $109337s2% of the player's maximum health, and creates a 10 yard radius area of frost underneath that player. The frost reduces any player's movement speed standing within the area by $109337s1%.",difficultyIDs={5,6}},
			{id=3918,title="Lightning Storm",body="Hagara channels a lightning storm to electrocute the players on the platform. A Water Shield protects Hagara from all attacks and spells.\n\nWhen players overload every Crystal Conductor, the feedback stops her channeling and causes her to suffer an Electrocution."},
			{id=3919,title="Crystal Conductor",body="Hagara conjures four Crystal Conductors to protect herself from the lightning storm.$[!5\n\nIn 10 player Heroic Difficulty, Hagara conjures eight Crystal Conductors.$]"},
			{id=4327,title="Lightning Conduit",body="A Crystal Conductor charged by the death of a Bound Lightning Elemental casts Lightning Conduit on the nearest player, inflicting $%105369s1 Nature damage every $105369t1 sec.\n\nLightning Conduit also connects the affected player to another player or Crystal Conductor within 10 yards."},
			{id=4070,title="Bound Lightning Elementals",body="Hagara calls elementals to aid her during the Lightning Storm. When a player kills an elemental,  it causes a nearby Crystal Conductor to overload and electrocute nearby players."},
			{id=4328,title="Storm Pillars",body="Hagara targets the location of a random player, then after 3 seconds a pillar of lightning erupts. The lightning inflicts $%109563s1 Nature damage to all players within $109563A1 yards.",difficultyIDs={5,6}},
			{id=4326,title="Feedback",body="The feedback from the overloaded Crystal Conductors and destroyed Binding Crystals stuns Hagara and increases her damage taken by $108934s1% for $108934d."},
		},
	},
	[318]={
		encounterID=318,
		instanceID=187,
		order=7,
		name="Spine of Deathwing",
		lore="When Deathwing first channeled the Dragon Soul's power against the other flights, the massive energies that were unleashed threatened to break apart his very body.  Rather than forgo this weapon, he had adamantium plates fused to his scales to hold his body together. Later reinforced with elementium, these plates are now his weakness--the sole vulnerability to Deathwing's lethal presence.",
		dungeonEncounterID=1291,
		uiMapID=414,
		pin={x=0.3321,y=0.8526},
		difficultyIDs={3,4,5,6,7},
		npcIDs={53879,56584},
		displayIDs={35268},
		loot={
			{itemID=78464,diffs={5,6},faction=-1},
