			{id=4256,title="Thrall",body="Thrall hurls molten lava at the Frozen Servitors above, keeping their numbers in check.",difficultyIDs={2,4}},
			{id=3944,title="Icy Tomb",body="Arcurion encases Thrall in an Icy Tomb. Destroying the Icy Tomb releases Thrall.",difficultyIDs={2,4}},
