		sections={
			{id=3955,title="The Calling of the Highborne",body="Sylvanas ascends towards the sky, pulling all of her enemies below her. Her calling then summons eight Risen Ghouls  in a circle around Sylvanas. A shadowy link forms between each ghoul, and the area behind each ghoul fills with shadows. The ghouls then march mindlessly towards Sylvanas. When a Risen Ghoul reaches Sylvanas, it performs the Sacrifice spell.\n\nCrossing any of the links between the Risen Ghouls or standing within the shadows behind the ghouls inflicts Wracking Pain every second on the player. Destroying a Risen Ghoul will sever the link to other nearby ghouls, and remove the area of shadows behind it.",difficultyIDs={2,4,5,6}},
			{id=4189,title="Wracking Pain",body="Crossing any of the links between the Risen Ghouls or standing within the shadows behind the ghouls inflicts Wracking Pain on the player every second. Wracking Pain inflicts $101221s1 Shadow damage.",difficultyIDs={2,4,5,6}},
			{id=4190,title="Risen Ghoul",body="When a Risen Ghoul reaches Sylvanas, it performs the Sacrifice spell.\n\nDestroying a Risen Ghoul will sever the link to other nearby ghouls, and remove the area of shadows behind it.",difficultyIDs={2,4,5,6}},
			{id=4191,title="Sacrifice",body="Sacrifice inflicts $101348s1 Shadow damage to players within $101348A1 yards of Sylvanas.",difficultyIDs={2,4,5,6}},
			{id=3951,title="Shriek of the Highborne",body="Sylvanas shrieks with anguish, inflicting $101412s1 Shadow damage on a random player and decreasing their movement speed by $101412s2% for $101412d.",difficultyIDs={2,4,5,6}},
			{id=3952,title="Black Arrow",body="Sylvanas fires an explosive black arrow at a random player, inflicting $101404s1 Shadow damage on players within $101404A1 yards of the target.",difficultyIDs={2,4,5,6}},
			{id=3953,title="Unholy Shot",body="Sylvanas targets a barrage of missiles at a random player, striking up to $101411x1 players within 10 yards of the target. Each missile inflicts $101411s1 Shadow damage and an additional $101411s2 Shadow damage  every $101411t2 sec. for $101411d.",difficultyIDs={2,4,5,6}},
			{id=3954,title="Blighted Arrows",body="Sylvanas blights the ground in a $103171A1 yard radius circle beneath a random player and leaps towards the sky. The blight inflicts $103171s1 damage every $101552t1 sec. and reduces the movement speed by $103171s2% of any player standing within it.\n\nAt the peak of her jump, she launches a volley of deadly arrows at the blighted ground. The arrows inflict $100763s1 Shadow damage and knock back any player still standing within the blight.",difficultyIDs={2,4,5,6}},
			{id=4162,title="Heroic Difficulty Only",body="End Time is only available in Heroic Difficulty.",difficultyIDs={1,3}},
		},
