	[324]={
		encounterID=324,
		instanceID=187,
		order=2,
		name="Warlord Zon'ozz",
		lore="Countless ages ago, Warlord Zon'ozz and his soldiers waged endless war against the forces of C'Thun and Yogg-Saron. Millennia have passed, but the warlord still serves the chaotic might of the Old God N'Zoth. Deathwing has now unleashed this legendary faceless one to crush the defenders of Wyrmrest Temple.",
