		sections={
			{id=3970,title="Focused Anger",body="Warlord Zon'ozz increasingly focuses his anger and rage, increasing his Physical damage done by $104543s2% and his attack speed by $104543s1% . This effect stacks."},
			{id=3971,title="Psychic Drain",body="Warlord Zon'ozz channels a wave of psychic force in a 30 degree cone in front of himself, inflicting $%104322s1 Shadow damage and leeching life for ten times the amount of damage dealt."},
			{id=3972,title="Disrupting Shadows",body="Warlord Zon'ozz covers random players with Disrupting Shadows. The effect inflicts $%103434s1 Shadow damage every $103434t1 seconds. The shadows also deal $103948s2 Shadow damage and knockback the targeted player if the effect is dispelled.$[!5,6\n\nIn Heroic Difficulty the effect deals $103948s2 Shadow damage and knocks back all players within $103948A1 yards.$]",difficultyIDs={1,2,3,4,5,6}},
			{id=4364,title="Disrupting Shadows",body="Warlord Zon'ozz covers random players with Disrupting Shadows. The effect inflicts $%103434s1 Shadow damage every $103434t1 seconds."},
			{id=3973,title="Void of the Unmaking",body="Warlord Zon'ozz summons a Void of the Unmaking. This void travels forward until it encounters a soul to absorb."},
			{id=4322,title="Void Diffusion",body="When the Void collides with a player it diffuses, inflicting $%103527s1 Shadow damage split evenly between nearby players. The force of this diffusion causes the void to ricochet in the opposite direction, and the absorbed souls increase the damage the Void inflicts by $106836s1% per diffusion.",difficultyIDs={1,2,3,4,5,6}},
			{id=4367,title="Void Diffusion",body="When the Void collides with a player it diffuses, inflicting 50,000 Shadow damage. The force of this diffusion causes the void to ricochet in the opposite direction, and the absorbed souls increase the damage the Void inflicts by 5% per diffusion."},
			{id=4475,title="Black Blood Eruption",body="If the Void of Unmaking reaches the outer edges of the Maw of Go'rath, it will spark a violent reaction. This eruption deals $%108794s2 Shadow damage to all targets within the maw, knocking them into the air."},
			{id=3988,title="Zon'ozz Diffused",body="When the Void collides with Warlord Zon'ozz, it inflicts a distracting shock to him. The Void Diffusion increases the damage Zon'ozz takes by $104031s1% for every time the Void of the Unmaking bounces between players. This collision enrages Warlord Zon'ozz, causing him to awaken the Maw of Go'rath and lose his Focused Anger.$[!5,6\n\nIn Heroic Difficulty the awakening of the Maw of Go'rath causes many different types of tentacles to emerge and attack the players.$]"},
			{id=4267,title="Black Blood of Go'rath",body="Warlord Zon'ozz inflicts $%104378s1 Shadow damage every $104378t1 sec. to all players for $104378d.$[!5,6\n\nIn Heroic Difficulty each tentacle of Go'rath inflicts $%104377s1 Shadow damage every $104377t1 sec. to all nearby enemies. The damage is multiplied by the number of tentacles alive.$]"},
			{id=3989,title="Claw of Go'rath",difficultyIDs={5,6}},
			{id=4263,title="Ooze Spit",body="When not tanked the Claw of Go'rath spits ooze at a random player, inflicting $%109396s1 Shadow damage to the target and any allies within $109396A1 yards.",difficultyIDs={5,6}},
			{id=3990,title="Eye of Go'rath"},
			{id=4265,title="Shadow Gaze",body="The Eye of Go'rath casts its Shadowy Gaze at a random player, inflicting $%104347s1 Shadow damage."},
			{id=4266,title="Flail of Go'rath",difficultyIDs={5,6}},
			{id=4268,title="Wild Flail",body="The Flail of Go'rath whips about wildly, inflicting $%109199s1 Physical damage and knocking back nearby enemies within $109199A1 yards.",difficultyIDs={5,6}},
			{id=4361,title="Sludge Spew",body="The Flail of Go'rath spews sludge at a random player, inflicting $%110297s1 Shadow damage.",difficultyIDs={5,6}},
		},
	},
