		sections={
			{id=3974,title="Void Bolt",body="Yor'sahj the Unsleeping blasts his primary target with dark energy, dealing $%104849s1 Shadow damage initially and then $%104849s2 Shadow damage every $104849t2 seconds. This effect stacks."},
			{id=3978,title="Call Blood of Shu'ma",body="Yor'sahj the Unsleeping calls to the might of Shu'ma, summoning three differently colored globules of his blood. These globules path slowly towards Yor'sahj, infusing him with additional powers if they reach him.$[!5,6\n\nIn Heroic difficulty four slimes answer Yor'sahj's call.$]"},
			{id=3979,title="Fusing Vapors",body="The blood globules emit a fusing vapor when damaged below 50% health that heals all other active globules for $103635s1% of their maximum life.\n\nWhen one globule dies, the surviving globules completely fuse and gain immunity to all forms of damage."},
			{id=3980,title="Glowing Globule",body="When a Glowing Globule reaches Yor'sahj, it infuses Yor'sahj with the Glowing Blood of Shu'ma."},
			{id=4317,title="Glowing Blood of Shu'ma",body="Yor'sahj's Void Bolt now hits all nearby targets for $%105416s1 Shadow damage in addition to the primary target component, Yor'sahj uses his abilities twice as often, and his attack speed increases by $104901s1%."},
			{id=3981,title="Cobalt Globule",body="When a Cobalt Globule reaches Yor'sahj, it infuses Yor'sahj with the ability to summon Mana Voids."},
			{id=4318,title="Mana Void",body="A Mana Void leeches all the mana from every ranged spell caster and healer, storing the mana within itself. Destroying the Mana Void evenly returns the total of the leeched mana via Mana Diffusion to players within $105539A1 yards.",difficultyIDs={1,2,3,4,5,6}},
			{id=4507,title="Mana Void",body="A Mana Void leeches all the mana from every ranged spell caster and healer, storing the mana within itself. Destroying the Mana Void evenly returns the total of the leeched mana via Mana Diffusion to players within $110742A1 yards."},
			{id=3982,title="Crimson Globule",body="When a Crimson Globule reaches Yor'sahj, it infuses Yor'sahj with the Searing Blood ability."},
			{id=4319,title="Searing Blood",body="Yor'sahj sears the blood of three random players, inflicting a base of $%105033s1 Fire damage. The further the target stands from Yor'sahj, the greater shock received from the blast.$[!4,6\n\nIn 25 player raids, Yor'sahj sears the blood of eight random players.$]"},
			{id=3983,title="Dark Globule",body="When a Dark Globule reaches Yor'sahj, the corruption of the blood seeps out into the Maw of Shu'ma. This vile corruption then periodically creates Forgotten Ones that attack the players."},
			{id=3984,title="Forgotten One",body="These creatures fixate on a random target."},
			{id=3985,title="Psychic Slice",body="The Forgotten One emits a wave of psychic force at its current target, inflicting $%105671s1 Shadow damage."},
			{id=3986,title="Acidic Globule",body="When an Acidic Globule reaches Yor'sahj, the Maw of Shu'ma infuses with the acidic blood and stimulates further Digestive Acid production."},
			{id=4320,title="Digestive Acid",body="Digestive Acid periodically secretes from the stomach lining, inflicting $%105573s1 Nature damage to a player and nearby allies within $105573A1 yards.",difficultyIDs={1,2,3,4,5,6}},
			{id=4365,title="Digestive Acid",body="Digestive Acid periodically secretes from the stomach lining, inflicting $%105573s1 Nature damage to a random player."},
			{id=3987,title="Shadowed Globule",body="When a Shadowed Globule reaches Yor'sahj, it infuses Yor'sahj with the Deep Corruption ability."},
			{id=4321,title="Deep Corruption",body="Yor'sahj's Deep Corruption spreads to every player, causing every fifth healing or absorption effect cast on a player to trigger a violent detonation, inflicting $%105173s1 Shadow damage to all players."},
		},
	},
