		sections={
			{id=4040,title="Stage One: The Final Assault",body="Deathwing assaults his enemies while attached to the platforms by his twisted limbs."},
			{id=4037,title="Assault Aspect",body="Deathwing searches for his next enemy to assault.  Deathwing assaults the platform with the largest number of players and an attached limb."},
			{id=4102,title="Cataclysm",body="Deathwing attempts to finish the job he started by bringing forth a second Cataclysm, inflicting $%106523s1 Fire damage to all players."},
			{id=4106,title="Elementium Bolt",body="Deathwing creates an Elementium Bolt, sending it to the target platform."},
			{id=4107,title="Elementium Blast",body="If the Elementium Bolt reaches its destination, the bolt inflicts $%105723s1 Fire damage to all players and an additional $105723s2 Fire damage every $105723t2 sec until players destroy the Elementium Bolt. The initial damage decreases the further the player stands from the targeted location."},
			{id=4347,title="Corrupting Parasite",body="A Corrupting Parasite inflicts increasing Shadow damage periodically. When Corrupting Parasite's duration ends, the parasite detaches from the player and causes a Parasitic Backlash. This inflicts $%108787s1 Fire damage to players within $108787A1 yards of the host.",difficultyIDs={5,6}},
			{id=4348,title="Corrupting Parasite",body="After the Corrupting Parasite's duration ends, the parasite detaches from the host.",difficultyIDs={5,6}},
			{id=4349,title="Unstable Corruption",body="The Corrupting Parasite casts Unstable Corruption, inflicting $108813s1% of the Corrupted Parasite's health as Fire damage to all players.",difficultyIDs={5,6}},
			{id=4108,title="Hemorrhage",body="Deathwing's tentacle begins to Hemorrhage, creating several Regenerative Blood at a nearby location."},
			{id=4109,title="Regenerative Blood",body="The Regenerative Blood of Deathwing forms. Regenerative Bloods gain ten energy every $105932t1 sec.  The melee attacks of a Regenerative Blood also cause Degenerative Bite."},
			{id=4110,title="Regenerative",body="A Regenerative Blood heals to full health when it reaches maximum energy.$[!7\n\nIn Raid Finder Difficulty, Regenerative Blood heals 50% of max health when it reaches maximum energy.$]"},
			{id=4111,title="Degenerative Bite",body="Melee attacks cause Degenerative Bite, inflicting $%105841s1 Shadow damage every $105841t1 sec for $105841d. This effect stacks."},
			{id=4038,title="Limb Tentacle",body="Deathwing grasps onto each platform with one of his limbs."},
			{id=4039,title="Burning Blood",body="The Burning Blood gushes from the Tentacle, inflicting Fire damage every $105401t1 sec. The damage increases as the Limb Tentacle's health lowers."},
			{id=4103,title="Blistering Tentacle",body="At 75%, 50%, and 25% remaining health the Limb Tentacle sprouts several Blistering Tentacles that are immune to Area of Effect abilities."},
			{id=4104,title="Blistering Heat",body="The Blistering Heat inflicts $%105445s1 Fire damage every $105444t1 sec, and increases its damage by $105445s2% for $105445d. This effect stacks."},
			{id=4105,title="Agonizing Pain",body="The pain from severing Deathwing's limb interrupts his concentration, stunning him and inflicting $106548s1% of his health in damage."},
			{id=4112,title="Mutated Corruption",body="A Mutated Corruption appears shortly after assaulting a platform."},
			{id=4113,title="Crush",body="The crushing weight of the Mutated Corruption inflicts $%106385s1 Physical damage to enemies in a cone in front of the Corruption."},
			{id=4114,title="Impale",body="The Mutated Corruption impales its target, inflicting $%106444s1 Physical damage to the target."},
			{id=4046,title="Stage Two: The Last Stand",body="At 20% remaining health, Deathwing falls forward onto the platform."},
			{id=4350,title="Congealing Blood",body="Deathwing begins to Hemorrhage, creating several Congealing Blood at a nearby location. The Blood then moves towards Deathwing.",difficultyIDs={5,6}},
			{id=4351,title="Congealing Blood",body="If a Congealing Blood reaches Deathwing, it heals him for $109102s1% of his maximum health.",difficultyIDs={5,6}},
			{id=4115,title="Elementium Fragment",body="Pieces of Deathwing's armor chip off, forming three Elementium Fragments nearby.$[!4,6,7\n\nIn 25 player raids, eight Elementium Fragments form.$]"},
			{id=4116,title="Shrapnel",body="The Fragment fires a piece of Shrapnel at a random player, inflicting $%106791s1 unresistable Physical damage."},
			{id=4117,title="Elementium Terror",body="Pieces of Deathwing's armor chip off, forming two Elementium Terrors nearby."},
			{id=4118,title="Tetanus",body="The Elementium Terror's melee attacks cause Tetanus, inflicting $%106730s2 Physical damage and an additional  $%106730s1 Physical damage every $106730t1  sec. The effect stacks."},
			{id=4119,title="Corrupted Blood",body="Corrupted Blood gushes from Deathwing, inflicting Fire damage every $106834t1 sec. The damage increases as Deathwing's health lowers. At 15%, 10%, and 5% remaining health, Deathwing hemorrages. This increases the damage dealt by Corrupted Blood."},
			{id=4123,title="The Aspects",body="The Dragon Aspects assist in the fight against Deathwing. Each aspect channels Expose Weakness on their respective Limb Tentacle when Deathwing begins to cast Cataclysm. Expose Weakness increases the damage done to the Tentacle by 100%. \n\nEach Aspect also channels Concentration after the players destroy their respective tentacle, preventing the Aspect from assisting the players with their presence and their special powers. The Aspects resume assisting the players when Stage Two begins."},
			{id=4124,title="Alexstrasza"},
			{id=4125,title="Alexstrasza's Presence",body="The Presence of Alexstrasza increases the player's maximum health by $106028s1%."},
			{id=4126,title="Cauterize",body="Alexstrasza Cauterizes the Blistering Tentacles, inflicting lethal damage over $105565d. Cauterize also reduces the damage inflicted by Corrupted Blood.$[!5,6\n\nIn Heroic Difficulty Alexstrasza Cauterizes the Corrupting Parasite, inflicting $109045s1% Fire damage every $108840t1 sec.$]"},
			{id=4127,title="Nozdormu"},
			{id=4128,title="Nozdormu's Presence",body="The Presence of Nozdormu increases the player's haste by $106027s1%."},
			{id=4129,title="Time Zone",body="Nozdormu forms a Time Zone at the target location, causing the Elementium Meteor to lapse in time and decrease its travel speed dramatically upon entering the zone. Any enemy creatures within the Time Zone have their attack speed decreased by $105830s1%.$[!5,6\n\nIn Heroic Difficulty the Time Zone slows the effects of Corrupting Parasite.$]"},
			{id=4130,title="Ysera"},
			{id=4131,title="Ysera's Presence",body="The Presence of Ysera increases player healing done by $106457s1%."},
			{id=4132,title="Enter the Dream",body="The Presence of Ysera allows players to enter the Dream, decreasing damage taken by $106466s1% for $106466d."},
			{id=4133,title="Kalecgos"},
			{id=4134,title="Kalecgos' Presence",body="The Presence of Kalecgos increases player damage dealt by $106029s1%."},
			{id=4135,title="Spellweaving",body="The Presence of Kalecgos allows attacks and abilities to cause Spellweaving. Spellweaving inflicts $106043s2 Arcane damage to enemies within $106043A2 yards, excluding the current target."},
			{id=4136,title="Thrall"},
			{id=4137,title="Carrying Winds",body="The Carrying Winds take players between adjacent platforms, and increase their movement speed by $106664s1% for $106664d. This effect stacks."},
		},
	},
