		sections={
			{id=4120,title="Skewer",body="Alizabal skewers and stuns her current target for $104936d. Skewer also inflicts $104936s2 Physical damage every $104936t2 sec. and increases the target's damage taken by $104936s3%.",difficultyIDs={3,4}},
			{id=4121,title="Seething Hate",body="Alizabal incites Seething Hate in a random player, inflicting $105069s1 total Fire damage to all players within $105069A1 yards of the target every 3 sec. The damage is split amongst all of the nearby players.",difficultyIDs={3,4}},
			{id=4122,title="Blade Dance",body="Alizabal enters a Blade Dance and inflicts $104994s1 Physical damage every sec. increasing over time, to every player within $104994A1 yards. The Blade Dance also deflects all incoming attacks.",difficultyIDs={3,4}},
			{id=18668,title="Normal Difficulty Only",body="Baradin Hold is only available on Normal Difficulty.",difficultyIDs={5,6}},
