	[340]={
		encounterID=340,
		instanceID=184,
		order=1,
		name="Echo of Baine",
		lore="Enraged by his failure to protect the world and, most importantly, the Horde, this time-ravaged shade of Baine Bloodhoof lingers within the ruins of the Obsidian Dragonshrine. Although he's still as powerful as the tauren high chieftain from the present, within this shattered future Azeroth, this guilt-ridden echo is little more than a discordant vessel of unquenchable malice and anger.",
		dungeonEncounterID=1881,
		uiMapID=404,
		pin={x=0.3672,y=0.531},
