			{id=4139,title="Molten Fists",body="Players' fists ignite for $101866d. when they come into contact with lava. The ignited fists cause melee attacks to inflict an additional $101867s1 Fire damage.",difficultyIDs={2,4,5,6}},
			{id=4140,title="Pulverize",body="The Echo of Baine slams the ground with his totem, inflicting $101627s1 Physical damage to enemies within $101627A1 yards and destroying the nearby platform.",difficultyIDs={2,4,5,6}},
			{id=4141,title="Throw Totem",body="The Echo of Baine throws his totem at a random player, inflicting $101614s1 Physical damage and knocking them back.  The totem then persists on the ground at the target's location for $101614d.",difficultyIDs={2,4,5,6}},
			{id=4142,title="Throw Totem",body="A player may attempt to throw the totem back at the Echo of Baine. A successful throw inflicts $101602s1% of the Echo of Baine's maximum health as Physical damage, stuns him, and increases his damage taken by $101602s2% for $101866d.",difficultyIDs={2,4,5,6}},
