	[341]={
		encounterID=341,
		instanceID=186,
		order=3,
		name="Archbishop Benedictus",
		lore="Archbishop Benedictus is the revered leader of the Church of the Holy Light. For years, his wise guidance has been instrumental in seeing humanity through bleak times. Yet beneath his apparent benevolence lies the shocking truth that Benedictus has pledged himself to the eradication of all life on Azeroth through the agency of his dark master... Deathwing.",
		dungeonEncounterID=1339,
		uiMapID=400,
		pin={x=0.4738,y=0.5138},
		difficultyIDs={2,236},
		npcIDs={54938},
		displayIDs={38991},
		loot={
			{itemID=72864,diffs={},faction=-1},
			{itemID=72865,diffs={},faction=-1},
			{itemID=72866,diffs={},faction=-1},
			{itemID=72867,diffs={},faction=-1},
			{itemID=72900,diffs={},faction=-1},
			{itemID=72868,diffs={},faction=-1},
			{itemID=72901,diffs={},faction=-1},
			{itemID=72869,diffs={},faction=-1},
			{itemID=72870,diffs={},faction=-1},
			{itemID=72861,diffs={},faction=-1},
			{itemID=72862,diffs={},faction=-1},
			{itemID=72863,diffs={},faction=-1},
		},
		sections={
			{id=4150,title="Stage One: The Light Will Consume You!",body="Benedictus assaults Thrall with the powers of the Holy Light.",difficultyIDs={2,4}},
			{id=4143,title="Righteous Shear",body="Archbishop Benedictus targets a random player with Righteous Shear, inflicting Holy damage to players within $103161A1 yards of the target per stack of Righteous Shear.",difficultyIDs={2,4}},
			{id=4144,title="Purifying Light",body="Archbishop Benedictus forms three orbs of Purifying Light and raises them above his head, sending them to assault a nearby player and causing a Purifying Blast.",difficultyIDs={2,4}},
			{id=4151,title="Purifying Blast",body="Archbishop Benedictus' Purifying Blast inflicts $103651s1 Holy damage to players within $103651A1 yards.",difficultyIDs={2,4}},
			{id=4145,title="Wave of Virtue",body="Archbishop Benedictus summons a Wave of Virtue to sweep across the platform, inflicting $103684s1 Holy damage to nearby players and knocking them back.",difficultyIDs={2,4}},
			{id=4152,title="Stage Two: Drown in Shadow!",body="At 60% remaining health Archbishop Benedictus casts Twilight Epiphany, showing his true form, transforming into an agent of the Twilight and trapping Thrall in a Twilight Prison.",difficultyIDs={2,4}},
			{id=4153,title="Twilight Shear",body="Archbishop Benedictus targets a random player with Twilight Shear, inflicting Shadow damage to players within $103526A1 yards of the target per stack of Twilight Shear.",difficultyIDs={2,4}},
			{id=4154,title="Corrupting Twilight",body="Archbishop Benedictus forms three orbs of Corrupting Twilight and raises them above his head, sending them to assault a nearby player and causing a Twilight Blast.",difficultyIDs={2,4}},
			{id=4155,title="Twilight Blast",body="Archbishop Benedictus' Twilight Blast inflicts $103777s1 Shadow damage to players within $103777A1 yards.",difficultyIDs={2,4}},
			{id=4156,title="Wave of Twilight",body="Archbishop Benedictus summons a Wave of Twilight to sweep across the platform, inflicting $103781s1 Shadow damage to nearby players, knocking them back.",difficultyIDs={2,4}},
			{id=4146,title="Thrall",body="Thrall will assist his allies in combat with Archbishop Benedictus.",difficultyIDs={2,4}},
			{id=4147,title="Cleanse Spirit",body="Thrall cleanses the spirit, dispelling one stack of a magic effect.",difficultyIDs={2,4}},
			{id=4148,title="Chain Lightning",body="Thrall lashes out at the Purifying Light with Chain Lightning, destroying them.",difficultyIDs={2,4}},
			{id=4157,title="Water Shell",body="Thrall's Water Shell protects allies from the Wave of Virtue and increases their damage done by $103744s1%.",difficultyIDs={2,4}},
			{id=4149,title="Heroic Difficulty Only",body="Hour of Twilight is only available on Heroic Difficulty.",difficultyIDs={1,3}},
		},
	},
	[342]={
		encounterID=342,
		instanceID=186,
		order=2,
		name="Asira Dawnslayer",
		lore="Former blade-for-hire Asira Sunbright was initially leery of working for the Twilight's Hammer, but the cult's generous payments quickly won her over. In time, she succumbed to the corruptive influence of her dark employers, even going so far as to take the name Dawnslayer. As one of the cult's deadliest assassins, Asira has been called upon to exterminate Thrall and his comrades.",
		dungeonEncounterID=1340,
		uiMapID=399,
		pin={x=0.4077,y=0.5094},
		difficultyIDs={2,236},
		npcIDs={54968},
		displayIDs={38995},
		loot={
			{itemID=72856,diffs={},faction=-1},
