		sections={
			{id=4167,title="Mark of Silence",body="Asira marks a random enemy spellcaster for $102726d. When a marked target casts a spell, Asira throws a knife in their direction.",difficultyIDs={2,4}},
			{id=4169,title="Throw Knife",body="Asira throws one of her knives toward a marked enemy spellcaster, inflicting $103597s2 Physical damage to the first player it collides with. If the knife hits a player afflicted with Mark of Silence, it also silences for $103587d.",difficultyIDs={2,4}},
			{id=4170,title="Choking Smoke Bomb",body="Asira creates a cloud of thick smoke in an $103558A1 yard radius around her for $103558d. The cloud prevents enemies from targeting into or out of the smoke cloud and inflicts $103790s2 Nature damage every $103558t2 sec.",difficultyIDs={2,4}},
			{id=4171,title="Blade Barrier",body="At 30% remaining health, Asira begins a dazzling display of weapon mastery. Her Blade Barrier reduces any incoming amount of damage below $103419s1 to 1. The Blade Barrier ends when a player hits Asira with a damaging attack or spell above this threshold.",difficultyIDs={2,4}},
			{id=4175,title="Lesser Blade Barrier",body="Asira erects this weaker barrier when a player removes Blade Barrier. The Lesser Blade Barrier reduces any incoming amount of damage below $103562s1 to 1. The Lesser Blade Barrier ends when a player hits Asira with a damaging attack or spell above this threshold.",difficultyIDs={2,4}},
			{id=4168,title="Thrall",body="Thrall assists the players in combat against Asira.",difficultyIDs={2,4}},
			{id=4172,title="Lava Burst",body="Thrall hurls molten lava at the target, inflicting $107980s1 Fire damage.",difficultyIDs={2,4}},
			{id=4173,title="Rising Fire Totem",body="Thrall summons a Fire Totem that periodically increases the damage and maximum health of nearby players. The totem lasts $108374d and its effect can stack up to $103817u times.",difficultyIDs={2,4}},
			{id=4174,title="Healing Wave",body="Thrall calls upon Nature magic to heal himself.",difficultyIDs={2,4}},
			{id=4166,title="Heroic Difficulty Only",body="Hour of Twilight is only available in Heroic difficulty.",difficultyIDs={1,3}},
		},
	},
