		sections={
			{id=30295,title="Overview",body="Drahga Shadowburner weakens his foes with |cFF2959D3|Hspell:450095|h[Curse of Entropy]|h|r and summons Invoked Shadowflame Spirits that explode with |cFF2959D3|Hspell:75238|h[Shadowflame Nova]|h|r.\n\nAt 1% health, Drahga forces the subjugated Twilight dragon Valiona to aide him in battle. Valiona knocks back players with |cFF2959D3|Hspell:456751|h[Twilight Buffet]|h|r and scorches them with |cFF2959D3|Hspell:448105|h[Devouring Flame]|h|r."},
			{id=30296,title="Tank",body="$bullet; Drahga Shadowburner sears his current target with |cFF2959D3|Hspell:447966|h[Shadowflame Bolt]|h|r."},
			{id=30297,title="Damage Dealers",body="$bullet;Invoked Shadowflame Spirit erupts with |cFF2959D3|Hspell:75238|h[Shadowflame Nova]|h|r upon reaching its target.\n\n$bullet;Valiona's |cFF2959D3|Hspell:456751|h[Twilight Buffet]|h|r inflicts Shadowflame damage to all players and knocks them back."},
			{id=30298,title="Healers",body="$bullet;Invoked Shadowflame Spirit erupts with |cFF2959D3|Hspell:75238|h[Shadowflame Nova]|h|r upon reaching its target.\n\n$bullet;|cFF2959D3|Hspell:450095|h[Curse of Entropy]|h|r reduces target's movement speed and abosrbs healing.\n\n$bullet;Valiona's |cFF2959D3|Hspell:456751|h[Twilight Buffet]|h|r inflicts Shadowflame damage to all players and knocks them back."},
			{id=29546,title="Drahga Shadowburner",body="Drahga Shadowburner fights the players alone until he is close to being defeated. He will then call on Valiona to join the fight. Drahga then continues to fight the players from on top of Valiona's back."},
			{id=29556,title="Section 8"},
			{id=29557,title="Invoked Shadowflame Spirit"},
			{id=29561,title="Section 10"},
			{id=29558,title="Section 7"},
			{id=29559,title="Section 8"},
			{id=29547,title="Burning Shadowbolt"},
			{id=29551,title="Valiona",body="Valiona will fight with Drahga until she reaches 50% remaining health, when she ejects Drahga and leaves him to face the players alone."},
			{id=29980,title="Section 9",difficultyIDs={1,2}},
